quests[14007] = { id = 14007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steady Shot", description = "I'm Bamm Megabomb, your personal trainer, <sir/ma'am>.\n\nI understand that you're interested in some new insight about being a {class}?\n\nLook. Just get some more experience , and you'll learn how to do more of what it is you do best. Helpful, right?\n\nSo go, get some more experience, then when you learn how to do something new go ahead and try it out on one of the dummies here.", completion = "There you go, boss!\n\nCome back anytime you want more training. I'll teach you what I know.", objectives = "Reach Level 3 to Learn Steady Shot, then shoot a Training Dummy with it 3 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14008] = { id = 14008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frost Nova", description = "I'm Fizz Lighter, your personal trainer, <sir/ma'am>.\n\nI understand that you're interested in some new insight about being a {class}?\n\nLook. Just get better at what you already know, and you'll learn how to do more of what it is you do best. Helpful, right?\n\nSo go, get some more experience, then when you learn how to do something new go ahead and try it out on one of the dummy's here.", completion = "There you go, boss!\n\nCome back anytime you want more training. I'll teach you what I know.", objectives = "Reach level 3 to learn Frost Nova, then cast the spell 2 times at a Training Dummy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14009] = { id = 14009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning the Word", description = "I'm Sister Goldskimmer, your personal trainer, <sir/ma'am>.\n\nI understand that you're interested in some new insight about being a {class}? \n\nLook. Just get some more experience , and you'll learn how to do more of what it is you do best. Helpful, right?\n\nSo go, get some more experience, then when you learn how to do something new go ahead and try it out on one of the dummies here.", completion = "There you go, boss!\n\nCome back anytime you want more training. I'll teach you what I know.", objectives = "Reach level 3 to learn Shadow Word: Pain, then cast the spell 3 times on a training dummy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14010] = { id = 14010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eviscerate", description = "I'm Slinky Sharpshiv, your personal trainer, <sir/ma'am>.\n\nSo ya wanna get better at being a rogue, eh?\n\nLook. Just get some more experience , and you'll learn how to do more of what it is you do best. Helpful, right?\n\nSo go, get some more experience, then when you learn how to do something new go ahead and try it out on one of the dummy's here.", completion = "There you go, boss!\n\nCome back anytime you want more training. I'll teach you what I know.", objectives = "Reach Level 3 to Learn Eviscerate, then use it 3 times on a Training Dummy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14011] = { id = 14011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Strike", description = "I'm Maxx Avalanche, your personal trainer, <sir/ma'am>.\n\nI've been hearing your name around here, thought you could use some training. Look no further.\n\nAs you get better at your job, you start to be able to do totally new, amazing things. Trust me, it works. I get paid to tell people about it all the time.\n\nAnyways, get better at being a shaman, and then use your new abilities on a training dummy to the southeast.", completion = "There you go, boss!\n\nCome back anytime you want more training. I'll teach you what I know.", objectives = "Reach level 3 to learn Primal Strike, then use it 2 times on a Training Dummy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14012] = { id = 14012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corruption", description = "I'm Evol Fingers, your personal trainer, <sir/ma'am>.\n\nI understand that you're interested in some new insight about being a {class}?\n\nLook. Just get some more experience , and you'll learn how to do more of what it is you do best. Helpful, right?\n\nSo go, get some more experience, then when you learn how to do something new go ahead and try it out on one of the dummies here.", completion = "There you go, boss!\n\nCome back anytime you want more training. I'll teach you what I know.", objectives = "Reach level 3 to learn Corruption, then cast it 3 times on a Training Dummy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14013] = { id = 14013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charge", description = "<The Warrior-Matic NX-01 comes online.>\n\nBoss {name} detected. I am Warrior-Matic NX-01.\n\nWarning: Insufficient Skill Detected! Please gain more experience to learn new skills. \n\nDemonstrate new skills against training dummies to continue training course.", completion = "{class}-Matic NX-01 is programmed to serve.\n\nReturn anytime you seek more training. This unit will teach you what it knows.", objectives = "Reach level 3 to learn Charge, then use it on a Training Dummy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14014] = { id = 14014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Our Stuff Back!", description = "Our bombs and tools! Those sneaky monkeys to the east stole them all in the dead of night!\n\nCan you go out there and get them back for us, {name}? Without those tools, we have absolutely no way to get off of this island!", progress = "Bomb-throwing monkeys?! The nerve!!!", completion = "<Sassy breathes a sigh of relief when she sees all of the tools and bombs that you recovered.>\n\nI thought we were doomed for sure. But now we can start working on a way to get off of this island!", objectives = "Retrieve 8 Crates of Tools.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14015] = { id = 14015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Incomplete Cartography", description = "You open the scroll, revealing a fairly accurate map of Gilneas with one exception.  The entirety of the area between the coast and the cliffs behind Grimmburg appears to be missing.\n\nThere are also arrows that appears to represent Horde movement deeper in Gilneas.  Mayor Armstead might find this to be of interest.", sourceObjective = "Bring the Soaked Map to Mayor Armstead in Grimmburg.You open the scroll, revealing a fairly accurate map of Gilneas with one exception. The entirety of the area between the coast and the cliffs behind Grimmburg appears to be missing.\n\nThere are also arrows that appears to represent Horde movement deeper in Gilneas. Mayor Armstead might find this to be of interest.", sourceObjectiveStatus = "unverified-source-field" }
quests[14016] = { id = 14016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Knight's Curse", description = "I wanted to remove the Black Knight's remains from the tournament grounds after your victory, but Confessor Paletress insisted that he receive a decent burial. Ever since, a dark presence has lingered in the cemetery and people are afraid to go there to visit the fallen.\n\nWould you visit the cemetery just past the eastern end of the tournament grounds and see if you can discover what's happening?", progress = "Have you investigated the Black Knight's gravesite?", completion = "<Crusader Rhydalla frowns.>\n\nDo you think they've been planning this? I suppose it doesn't matter, but I don't like the implication that we've been playing into their hands. Whatever is going on, we have to stop it.", objectives = "Crusader Rhydalla at the Argent Tournament Grounds wants you to investigate the Black Knight's Grave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14017] = { id = 14017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Knight's Fate", description = "You said the body was taken by cultists? I can only think of one place they would have gone, Deathspeaker's Watch, the encampment on the rise west of the tournament grounds.\n\nWhatever the cultists are doing must be stopped. The rumors I've heard can only be true, then. The infamous Doctor Kohler must be among the cultists, practicing his arts. Look for a rise or an altar overlooking the cultist camp, slay the doctor, and look for proof of his plans. Slow down his work in any other way you can.", progress = "Did you find out what they're doing with the Black Knight's remains?", completion = "The doctor will not have time to complete his work, but his plan is already in motion. From what you've reported, the Lich King's servants have reanimated and empowered the Black Knight and there's no telling what the knight's master has in mind. You have done well in uncovering this plot. I will tell High Crusader Adelard of your findings and together, we will alert the tournament's participants.", objectives = "Capture Doctor Kolher's Orders at Deathspeaker's Watch, then return to Crusader Rhydalla at the Argent Tournament Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14018] = { id = 14018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He Who Would Be Forgiven", description = "The voice of the goddess spoke to you at the moonwell, {name}. The cure for Relara lies to the east at Raynewood Tower. The one who has fallen into corruption.\n\nAvrus Illwhisper seeks forgiveness and redemption. It is up to you to assist him and in so doing, hopefully help my child as well.", completion = "<The satyr sneers, but when he realizes you are not here to chastise him, he changes his expression.>\n\nFinally, my redemption is at hand. I have waited long for this day and I think I know how to help you in turn.", objectives = "Speak with Avrus Illwhisper at Raynewood Tower in Ashenvale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14019] = { id = 14019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monkey Business", description = "We've got major problems with the monkeys in the jungle to the east. They've stolen all of our explosives, and now they're going around throwing them.\n\nSometimes at us!\n\nI had Fizz Lighter take some of his nitro and put it in these bananas. No monkey can resist a bunch of bananas!\n\nAll you have to do is go out there and feed them.", progress = "Did it work?", completion = "They launched up into the air when they ate the bananas?! That is hilarious!\n\nI think I'm going to take a bunch out there and feed them myself!", objectives = "Feed 10 Bomb-Throwing Monkeys by tossing Nitro-Potassium Bananas to them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14020] = { id = 14020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Curse", description = "The Curse caught us by surprise.  Everything was normal one day, entire villages were turned into packs of howling worgen the next.BBy Lord Greymane's orders we toiled night and day to find a cure for it.  Alas, we did not.\n\nWe found the next best thing, however.  The distilled essence of the black mandrake allows us to mitigate most of the Curse's effects.\n\nUnfortunately, my supply has been cut off by this orc attack.  Bring me any black mandrake you find so I can distill more of the essence.", objectives = "Krennan Aranas in Grimmburg wants you to obtain 8 Black Mandrakes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14021] = { id = 14021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Miner Troubles", description = "Smart mining monkeys!\n\nThey're all over the inside of the cavern, mining... with picks! It's just not natural and I'm sure it's because of the kaja'mite!\n\nNone of my miners have come back out. I don't have many left! You can see my predicament, {name}.\n\n<The foreman lowers his voice.>\n\nThese guys are nowhere near as good as my old group of jungle trolls. Ah, those were the days.\n\nMaybe you can escort my last miner here through the cavern and keep those monkeys off of him? We need that kaja'mite!", progress = "How did it go? How much kaja'mite were you able to get?", completion = "We've hit the mother lode!!!\n\nNow, what's all this about a pygmy witchdoctor in charge of the monkeys? Is he dead? Because if he's dead, then legally I can stake my claim... not that I wasn't going to do that anyway. By {race} law, all Kaja'mite belongs to us!", objectives = "Escort the Frightened Miner through the Kaja'mite Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14022] = { id = 14022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilgrim's Bounty", description = "Won't you celebrate Pilgrim's Bounty with us, {name}? It's a time for reflecting on your journeys and your good fortune, sharing plentiful food and stories with friends.\n\nYou can partake of wonderful Pilgrim's Bounty feasts near major towns by sitting at a bountiful table and serving the foods you find there.\n\nIf you're interested in learning how to cook the traditional Pilgrim's Bounty foods, seek out Gregory Tabor. You will find him just outside Stormwind's gates.", completion = "If you'd like to learn to cook Pilgrim's Bounty foods, I can help. If you're not already a cook, all you have to do is train and you'll be cooking in no time!", objectives = "Speak with Gregory Tabor just outside the city gates of Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14023] = { id = 14023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spice Bread Stuffing", description = "Our spice bread stuffing is the cornerstone of the Pilgrim's Bounty table. The recipe has always been a favorite in Stormwind and now it has taken its place in the bountiful cookbook.\n\nIf you are already a cook, pay a visit to the Pilgrim's Bounty vendor to get your copy of the cookbook and all the local ingredients you'll need to prepare holiday fare. And if you're not yet a cook, there's no better time to start!\n\nOnce you've made the stuffing, bring it to Jasper Moore over near the tables.", progress = "We can always use more of that delicious spice bread stuffing. It's very popular.", completion = "Excellent. This is just what we needed. It's going to be a chore keeping all the tables stocked with fresh food, but it's well worth it.", objectives = "Cook 5 servings of Spice Bread Stuffing and then bring them to Jasper Moore at the feasting area just outside Stormwind's gates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14024] = { id = 14024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pumpkin Pie", description = "That spice bread stuffing you made smells delicious, but no Pilgrim's Bounty feast is complete without a slice of pumpkin pie. It's another one of our favorite dishes here in Stormwind, since it uses ripe Elwynn pumpkins that only grow here.\n\nIf you don't know how to make pumpkin pie already, there's a recipe in your bountiful cookbook.\n\nWould you mind cooking up a few slices and bringing them to Edward Winslow outside Ironforge? He's bound to be running low by now.", progress = "More pumpkin pie? Just in time.", completion = "The pumpkin pie's been a big hit up here. I've never seen a dwarf get so excited about anything made from a vegetable.", objectives = "Make 5 slices of Pumpkin Pie and bring them to Edward Winslow at the feasting area right outside Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14025] = { id = 14025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Frontlines" }
quests[14026] = { id = 14026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Off With a Bang" }
quests[14027] = { id = 14027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Face to Face", description = "My men can certainly use the help, {name}.  We're trying as hard as we can to hold the orcs back, but it's not good enough.\n\nKill as many orcs as it takes to tip the scales back in our balance.  Let's see if the ferocity your clan is known for is as good against the orcs as it is against our livestock.", objectives = "Lieutenant Wright wants you to kill 10 Orc Invaders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14028] = { id = 14028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cranberry Chutney", description = "If you haven't tried the cranberry chutney yet, you're in for a treat. It's made with the freshest tangy Wetlands cranberries. Just pick some up from the Pilgrim's Bounty vendor if you want to try your hand at making chutney.\n\nThe recipe should be in your bountiful cookbook.\n\nIf you've got some extra time on your hands, would you mind making some of the chutney and bringing it down to Jasper Moore outside Stormwind? I promised him I'd trade some for the pie you brought.", progress = "Is that cranberry chutney I smell?", completion = "Finally, the cranberry chutney I was promised. You wouldn't believe how fast the celebrants go through the stuff here.", objectives = "Make 5 servings of Cranberry Chutney and bring them to Jasper Moore at the feasting area outside Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14029] = { id = 14029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Siege" }
quests[14030] = { id = 14030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They're Ravenous In Darnassus", description = "Thanks for bringing the cranberry chutney. There's so much cooking to do, I hardly have time to think of anything else. And on top of my responsibilities here, Isaac Allerton in Darnassus is out of almost everything. I don't suppose you'd be willing to step in and whip up some more spice bread stuffing and pumpkin pie? The vendor should have all the ingredients you need\n\nYou should be able to find him near the feasting tables near the entrance to Darnassus just beyond the Warrior's Terrace.", progress = "Have you come to partake of the Pilgrim's Bounty feast?", completion = "Thanks for bringing everything. I was starting to get worried.\n\nWhile you're here, you should try your hand at making some candied sweet potatoes.", objectives = "Bring 5 servings of Spice Bread Stuffing and 5 Pumpkin Pies to Isaac Allerton near the entrance to Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14031] = { id = 14031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Capturing the Unknown", description = "Heya, {name}, there are strange cave paintings and other artifacts all over the cavern.\n\nDo you think you could use your belt-mounted KTC Snapflash camera to capture images at the designated spots? Also, snap a pic of the altar in the back of the cavern.\n\nI'm sure that Sassy will want the intel.", completion = "What are these?\n\n<Sassy examines the pictures while listening to your tale from the Kaja'mite cavern.>\n\nClearly that pygmy witchdoctor is from some new race never seen before. Maybe we should call them {name}-ians?\n\nThey must be the ones that painted all of that stuff in the cavern. I'm not sure that I like what you're describing.\n\nIt sounds to me like they're paintings of them and us on an island with an exploding volcano!", objectives = "Using your KTC Snapflash, capture images at the bouncing cameras of the three cave paintings and the pygmy altar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14032] = { id = 14032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kobold Camp Cleanup [Programming Test]", description = "Your first task is one of cleansing, {name}.  A clan of kobolds have infested the woods to the north.  Go there and fight the kobold vermin you find.  Reduce their numbers so that we may one day drive them from Northshire.", objectives = "Kill 10 Kobold Vermin, then return to Marshal McBride.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14033] = { id = 14033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candied Sweet Potatoes", description = "While you're here, you might want to stock up on Teldrassil sweet potatoes. They're used to make the most delicious candied sweet potatoes you've ever tasted.\n\nIf you don't believe me, look up the recipe in your bountiful cookbook and give it a try. And if there are any extras, you might want to share them with Gregory Tabor at the feasting area just outside Stormwind. They're one of his favorites, but to hear him tell it, everything's his favorite!", progress = "{name}, it's good to see you again.", completion = "Ah, candied sweet potatoes! My favorite! Did Isaac tell you?", objectives = "Make 5 servings of Candied Sweet Potatoes and bring them to Gregory Tabor just outside the gates of Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14034] = { id = 14034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Club Foote", description = "All this new friction between the Alliance and the Horde was leading to windfall profits, until Rear Admiral Hartley sailed into MY harbor and started poking his prow into my business. He's been searching and seizing vessels flying horde colors with the goal of depriving them use of a neutral port.\n\nI'm not about to allow some fat-fingered human to cut into my profits! Get me the schematics of his flagship. Hartley's Chief Engineer is soaking himself at the Broken Keel Tavern just up the hill...", progress = "You got the goods?", completion = "Ah, this is it - this is it right here! So his flagship is named \"The Bellipotent\" eh?\n\nLet's see what it'll take to send this nuisance to the bottom of the sea.", objectives = "Get the Ship Schematics from Chief Engineer Foote at the Broken Keel Tavern in Ratchet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14035] = { id = 14035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slow-roasted Turkey", description = "Every Pilgrim's Bounty feast requires a magnificent centerpiece, and I'm not talking about a decorative horn of plenty, either. No, the focus of the meal is a magnificent roast turkey.\n\nThere's a good recipe for it in your bountiful cookbook. Why not hunt some wild turkeys and prepare a few? The turkeys wander all over Elwynn Forest, so you shouldn't have a problem finding one.\n\nOnce you're done roasting them, will you bring them to Isaac Allerton near the gates of Darnassus?", progress = "What brings you back to Darnassus, {name}?", completion = "These are beautiful and just in time to feed hungry feasters. Thank you, {name}. You've truly mastered all the courses of a traditional Pilgrim's Bounty meal.", objectives = "Make 5 Slow-Roasted Turkeys and bring them to Isaac Allerton near the gates of Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14036] = { id = 14036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilgrim's Bounty", description = "Are you here to celebrate Pilgrim's Bounty with us? It was once a time for reflecting on your journeys and your good fortune while sharing a meal with friends. Many still mark the occasion.\n\nYou can partake of Pilgrim's Bounty feasts near major towns by sitting at a bountiful table and serving the foods you find there.\n\nIf you're interested in learning how to cook the traditional Pilgrim's Bounty foods, seek out Miles Standish. You will find him in the courtyard above Undercity.", completion = "If you'd like to learn to cook Pilgrim's Bounty foods, I can help. If you're not already a cook, all you have to do is train and you'll be cooking in no time.", objectives = "Speak with Miles Standish in the courtyard above Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14037] = { id = 14037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spice Bread Stuffing", description = "Our spice bread stuffing is the cornerstone of the Pilgrim's Bounty table. The recipe dates from better times in Lordaeron and now it has taken its place in the traditional meal.\n\nIf you are already a cook, pay a visit to the Pilgrim's Bounty vendor to get your copy of the bountiful cookbook and all the local ingredients you'll need to prepare holiday fare. And if you're not yet a cook, there's no better time to start!\n\nOnce you've made the stuffing, bring it to William Mullins over near the tables.", progress = "The tables could really use more of that spice bread stuffing.", completion = "It's a chore keeping all these tables stocked. If you stop and think about it, it's strange going to so much trouble when we needn't eat anymore.\n\n<William shrugs.>\n\nTradition is tradition.", objectives = "Cook 5 servings of Spice Bread Stuffing and then bring them to William Mullins at the feasting area in the courtyard above the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14038] = { id = 14038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Love it or Limpet", description = "<Gazlowe spreads the plans on the table and jabs a tiny finger aft of the ship below the waterline.>\n\nThere! The hull is thinnest here, where the crankshaft meets the paddlewheel. And it's right next to the magazine!\n\n{name}, I can't be held responsible if some enterprising Horde {class} were to attach a limpet mine to that part of the hull. Not even if I supplied the mine. And paid <him/her>. Handsomely. The ship is anchored just southeast of here... go to it!\n\nThen radio me with this stolen gnomecorder.", completion = "Excellent! I wish I could've seen the look on that Rear Admiral's face when his flagship went up like a candle. Let me use my telescope here to take a look at the damage.\n\nWhat - Whhhaaatt!? That thing is still floating? Hartley must've moved the munitions ashore in case his ship was mined.\n\nI underestimated you, Hartley... but for the last time!", objectives = "Plant a Limpet Mine at the thinnest part of the hull of the Bellipotent.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14039] = { id = 14039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home of the Kaldorei", description = "It has been an undeniable honor to have met you. You are a testament to the nobility of your race.\n\nGo now and finish this final task. Take the waters to Tyrande Whisperwind in Darnassus.", progress = "How fare you, young one?", completion = "Ah, the blessed waters from our moonwells. You have borne witness to the Spirit of the Kaldorei, then?\n\nIn recent times, I've come to find that the spirit offers more questions than it does answers, but such is the continuing nature of discovery that drives us in our darkest hours.\n\nI will offer you the simplest answers that I can. Malfurion has returned to me... to us... but harsh times are yet upon us. Staghelm is gone and the world is wracked with pain - Malfurion has much to mend, and he will need help.", objectives = "Bring the Filled Vessel to Tyrande Whisperwind in Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14040] = { id = 14040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pumpkin Pie", description = "That spice bread stuffing you made is a hit, but no Pilgrim's Bounty feast is complete without a slice of pumpkin pie. It's another traditional local dish, since it uses ripe Tirisfal pumpkins that only grow around here.\n\nIf you don't know how to make pumpkin pie already, there's a recipe in your bountiful cookbook.\n\nWould you mind cooking up a few slices and bringing them to Francis Eaton outside Orgrimmar? He's bound to be running low by now.", progress = "We can always use more pumpkin pie.", completion = "The pie always goes first. I think people must be skipping the meal and going directly for the dessert. Have you given it a try yet?", objectives = "Make 5 slices of Pumpkin Pie and bring them to Francis Eaton at the feasting area right outside Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14041] = { id = 14041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cranberry Chutney", description = "Have you tried the cranberry chutney yet? It's made with fresh tangy Southfury cranberries. Just pick some up from the Pilgrim's Bounty vendor if you want to try your hand at making chutney.\n\nThe recipe should be in your bountiful cookbook.\n\nIf you've got some extra time on your hands, would you mind making some of the chutney and bringing it to Dokin Farplain at the base of the elevator on the western side of Thunder Bluff?", progress = "How are you enjoying Pilgrim's Bounty, {class}?", completion = "Ah, more cranberry chutney! You wouldn't believe how fast the celebrants go through it.", objectives = "Make 5 servings of Cranberry Chutney and bring them to Dokin Farplain at the base of the elevator on the western side of Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14042] = { id = 14042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ammo Kerblammo", description = "Hartley must've unloaded all of his ordnance along the beach. Let's pull his teeth out, {name}!\n\nRun along the shore and look for his munitions stockpiles. Light 'em up and he'll be land-locked and unarmed while the Bellipotent is repaired.\n\nI'll meet you back here in Ratchet.", completion = "Hah! Beautiful work, {name}. Those Alliance cretins will never trace this back to me. Meanwhile, it's back to business as usual: smuggling, double-dealing, price-gouging... I've got a lot of work to catch up on.\n\nHere, I'll let you in on a cut of my future profits. Enjoy!", objectives = "Destroy 5 Theramore Ammunition Stockpiles along the coast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14043] = { id = 14043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candied Sweet Potatoes", description = "While you're here, you might want to stock up on Mulgore sweet potatoes. They're used to make delicious candied sweet potatoes, my favorite part of the Pilgrim's Bounty meal.\n\nIf you don't believe me, look up the recipe in your bountiful cookbook and give it a try. If you're headed back to Orgrimmar, bring them to Francis Eaton at the feasting area just outside the city. I've been trying to keep him supplied, but everything goes so fast over there.", progress = "Welcome back, {name}.", completion = "So Dokin drafted you to help with the candied sweet potatoes?\n\n<Francis smiles.>\n\nIt's the only way he can keep up. Thanks for bringing these.", objectives = "Make 5 servings of Candied Sweet Potatoes and bring them to Francis Eaton just outside of Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14044] = { id = 14044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undersupplied in the Undercity", description = "Thanks for bringing the candied sweet potatoes. There's so much cooking to do, I can hardly keep up. And then, Miles sends me a note saying he's on the verge of running out of stuffing and cranberry chutney. I don't suppose you'd be willing to step in and whip up some more of each? The vendor should have all the ingredients you need.\n\nYou should be able to find Miles Standish near the feasting tables in the courtyard in the ruins above Undercity.", progress = "It's good to see you again. {name}.", completion = "Thanks for bringing everything. Some of the tables were starting to look a little bereft of serving dishes.", objectives = "Bring 5 servings of Spice Bread Stuffing and 5 servings of Cranberry Chutney to Miles Standish near the entrance to Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14045] = { id = 14045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Baron Longshore", description = "That dirty pirate Baron Longshore was the terror of these waters before the Alliance demolished his fleet and rounded up the survivors. Am I happy about it? Do I look like a bundle of joy and good cheer, {name}?\n\nLongshore raided some of my most valuable cargo before his capture. Rumor has it he buried it before he was caught. I want my goods back! Find Longshore in the Alliance camp just south of here and see if you can get him to reveal where my treasure is.", completion = "Hah-har! So ol' Gazzy ain't given up on his goods yet, has he? Well, looks like that ol' floppy-eared goldgrubbler jes' gave me somethin' ta bargain with.", objectives = "Find and speak to the notorious pirate Baron Longshore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14046] = { id = 14046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Baron's Demands", description = "I'm bound fer that gallows fer sure, mate. That treasure's no good to me now...\n\nUnless I can use it ta buy me life. I'll make a deal with ye, {race}. Smash these manacles and I'll tell ye where me treasure's buried.\n\nOh, me word is good, friend. I used ta be a real Baron, ye know.", progress = "Get on with it, mate. The guards may be back any moment. Ye know what ta do.", completion = "<The Baron rubs his sore wrists, his face widening into a malevolent grin.>\n\nOh I won't be runnin' off just yet. I'll free me mates and murder my way out of here at a time of me choosin'. As fer you - a deal's a deal. Let's talk about that treasure...", objectives = "If you trust him, talk to Baron Longshore to free him from his manacles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14047] = { id = 14047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slow-roasted Turkey", description = "Every Pilgrim's Bounty feast requires a centerpiece, and for us, that's a slow-roasted wild turkey. I can't think of anything better to bring the meal together.\n\nThere's a good recipe for it in your bountiful cookbook. Why not hunt some wild turkeys and prepare a few? The turkeys wander all over Tirisfal Glades, so you shouldn't have a problem finding any.\n\nOnce you're done roasting them, will you bring them to Francis Eaton outside Orgrimmar?", progress = "What brings you back to Orgrimmar, {name}?", completion = "These look perfect. Thank you, {name}. You've truly mastered all the courses of a traditional Pilgrim's Bounty meal.", objectives = "Make 5 Slow-Roasted Turkeys and bring them to Francis Eaton near the gates of Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14048] = { id = 14048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can't Get Enough Turkey", description = "I've been cooking nonstop since before the start of the holiday, and I still can't keep up with the demand. I don't suppose I could persuade you to help with one of the dishes, could I?\n\nTurkey is hard to come by here, so if you could supply some slow-roasted turkeys, it would be a big help. If you intend to prepare them yourself, you can hunt fresh wild turkeys anywhere in Elwynn Forest. You should be able to buy everything else you need from any of the Pilgrim's Bounty vendors.", progress = "Did you manage to find those turkeys?", completion = "These are just what I need. Thanks, {name}. You're a lifesaver.", objectives = "Bring 20 Slow-Roasted Turkeys to Caitrin Ironkettle outside Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14049] = { id = 14049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Most Unusual Map", description = "Here's the deal, mate: to protect me treasure map, I tattooed it onto me first mate's scalp.\n\nOf course, he's dead now, along with most of me crew. The Alliance doesn't even know what they have - his severed head is hanging from a tree at the entrance to this camp.\n\nGrab that head and take it to Gazlowe back in Ratchet.", progress = "Was Baron Longshore alive? Do you have anything for me?", completion = "What? What is this? I send you out to fetch my treasure and you bring me a big filthy head?", objectives = "Get the Tattooed Head from the entrance to the Alliance compound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14050] = { id = 14050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gazlowe's Fortune", description = "Sink me, you were right! There's a map tattooed on the skull.\n\nThat cursed Baron - he buried my treasure right under my nose. Or, above my head, anyway. The map points to a place on the bluffs over Ratchet, to the south.\n\nFollow the road west out of the city, get atop the hill, head south, then run back towards the coast and look for an enormous tree overlooking the bay. Fetch my treasure and I'll split it with you!", progress = "I'm going to close my eyes, {name}. And when I open them, I expect to see wall-to-wall treasure. Deal?", completion = "Nice work, {name}!\n\nOh, the Baron tried to stop you, did he? Well, I hope you gave him a pounding.\n\nNow, I promised you a cut of the goods you recovered. Let's see... what's one percent of a half percent? Ah, here you go.", objectives = "Gazlowe wants you to dig up his buried treasure from atop the cliffs overlooking Ratchet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14051] = { id = 14051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Forget The Stuffing!", description = "Keeping these tables stocked can be overwhelming! I've got to make the cranberry chutney while keeping my eye on the sweet potatoes, and making sure the pies don't burn.\n\nI think I've got everything covered. No, wait, I'm forgetting something. The stuffing! Oh, no. There won't be time to get another batch of stuffing started before everything else is done. Would you be willing to help me out? It shouldn't take long to buy or make some stuffing and you can buy the ingredients right here.", progress = "Were you able to get that stuffing?", completion = "Thank goodness! I wouldn't be able to serve the feast without spice bread stuffing.", objectives = "Bring 20 Spice Bread Stuffing to Caitrin Ironkettle at the feasting area outside Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14052] = { id = 14052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take it up with Tony", description = "This pirate situation is really crimping my operation. Cap'n Garvey is attacking any vessel in sight, even the ones whose owners paid me my bogus \"protection\" money. We need to get these pirates on the take, and fast!\n\nI know just the guy, one of Garvey's Lieutenants who's open to wheeling and dealing the Dizzywig way. He's offered to arrange a little 'mutiny' for me. Once we get these guys working for us, it's all gravy, see?\n\nTalk to my boy Tony Two-Tusk on Fray Island to the south.", completion = "Hey hey mon, did Dizzywig send you? Good, good. Did you bring the money? No? ...what about the guns?", objectives = "Talk to Tony Two-Tusk on Fray Island in Northern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14053] = { id = 14053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We're Out of Cranberry Chutney Again?", description = "My husband, Jasper, was going to make more cranberry chutney, but it looks like he's busy trying to make sure there's enough candied sweet potatoes for all the guests. Would you be willing to help? If you're a cook, you can get the tangy Wetlands cranberries you'll need from the Pilgrim's Bounty vendor outside Ironforge.\n\nIf you don't feel up to cooking, you could always ask someone else to make the chutney, too.", progress = "Were you able to get your hands on any cranberry chutney?", completion = "Thanks. This looks great, and you're a fair bit faster than Jasper, but don't tell him I said so.", objectives = "Bring 20 servings of Cranberry Chutney to Ellen Moore at the feasting area outside Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14054] = { id = 14054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Easy As Pie", description = "Isaac's been hard at work helping celebrants learn about the traditional Pilgrim's Bounty feast and how to make dishes out of all the ingredients we harvest at this time of year. I've been trying to keep the tables stocked with as many of the dishes as I can, but we're running out of one of Isaac's favorites, pumpkin pie.\n\nWould you be able to get some for us? If you want to make the pies yourself, you'll need to buy ripe Elwynn pumpkins from the Pilgrim's Bounty vendor outside Stormwind.", progress = "How are those pies coming along?", completion = "These are perfect. Isaac, and everyone else, will love them!", objectives = "Bring 20 pieces of Pumpkin Pie to Mary Allerton at the feasting area near the gates of Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14055] = { id = 14055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "She Says Potato", description = "My wife Ellen has enlisted my help in keeping the tables stocked, but she can't make up her mind. First I was making pumpkin pie, but now she's changed her mind and she wants candied sweet potatoes.\n\nWell, I've already started on the pie, so maybe you can help me whip up those sweet potatoes. She'll be pleasantly surprised if we can get everything she's asked for.\n\nIf you're going to cook the sweet potatoes yourself, you'll have to buy them from the Pilgrim's Bounty merchant in Darnassus. Thanks, {name}.", progress = "Do you have those candied sweet potatoes?", completion = "These are perfect. Thanks for helping me with this, {name}. The meal will get served on time and Ellen will be happy.", objectives = "Bring 20 Candied Sweet Potatoes to Jasper Moore at the feasting area outside of Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14056] = { id = 14056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glomp is Sitting On It", description = "What? Leave it to Dizzywig to expect a mutiny on the cheap.\n\nNo matter, mon, we can make this work. First we need the money. Cap'n Garvey likes to hoard the loot we've been earnin', money I can use to pay off my handpicked mutineers.\n\nThe treasure pile is just outside the barracks here. You'll need to take care of Cap'n Garvey's \"treasurer\" first. Now, Glomp ain't no pushover. Believe me, I tried pushing him over once. He don't budge for nothin'.", progress = "You got the cash? That money will go a long way to winnin' over the hearts and minds of heartless, thoughtless cutthroats.", completion = "Look at that. We're loaded! In mutiny, you gotta make the money first. Then when you get the money, you get the power. Let's go get some power, {name}...", objectives = "Kill Glomp and grab Glomp's Booty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14057] = { id = 14057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guns. We Need Guns.", description = "Now, any good mutiny is going to need serious firepower. Cap'n Garvey claimed all the best firearms for himself: A whole shipment of big, heavy dwarven flintlocks. He keeps them at his side in the other building across the island. Grab me six of those rifles and I'll distribute them to me future officers...", progress = "Guns, mon. You got the stuff?", completion = "<Tony unhinges one of the weapons and peers down the barrel.>\n\nOooh, very nice. Shiny. Loud. Now we're talkin'.\n\nNot much left to do but close the deal...", objectives = "Gather six Heavy Dwarven Rifles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14058] = { id = 14058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "She Says Potato", description = "Roberta Carter has recruited me to help prepare one of the feast dishes, candied sweet potatoes.  Normally, I'd love to help, but I've promised the hostess that I'd help her watch the tables.\n\nI'd really appreciate it if you would help me come up with those candied sweet potatoes. Roberta would never forgive me if I let her down.\n\nIf you're going to cook the sweet potatoes yourself, you'll have to buy them from the Pilgrim's Bounty merchant in Thunder Bluff. Thanks, {name}.", progress = "Do you have those candied sweet potatoes?", completion = "Thanks, {name}. Now, I can help the hostess out and still keep my word to Roberta.", objectives = "Bring 20 Candied Sweet Potatoes to William Mullins at the feasting area above Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14059] = { id = 14059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We're Out of Cranberry Chutney Again?", description = "I wish I knew why we're going through cranberry chutney so fast. Sometimes, I think they're feeding it to the abominations when I'm not looking. Would you be willing to help me make up a new batch? If you're a cook, you can get the tangy Southfury cranberries you'll need from the Pilgrim's Bounty vendor outside Orgrimmar.\n\nIf you don't feel up to cooking, you could always ask someone else to make the chutney, too.", progress = "Were you able to get your hands on any cranberry chutney?", completion = "Thanks for your help, and let me know if you ever get to the bottom of the case of the disappearing chutney.", objectives = "Bring 20 servings of Cranberry Chutney to Roberta Carter at the feasting area in the courtyard above Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14060] = { id = 14060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Easy As Pie", description = "Dokin and Laha have been hard at work helping celebrants learn about the traditional Pilgrim's Bounty feast and how to make dishes out of all the ingredients we harvest at this time of year. I've been trying to keep the tables stocked with as many of the dishes as I can, but we're running low on pumpkin pie.\n\nWould you be able to get some for us? If you want to make the pies yourself, you'll need to buy ripe Tirisfal pumpkins from the Pilgrim's Bounty vendor outside the Undercity.", progress = "How are those pies coming along?", completion = "These are great! Thank you for helping, {name}.", objectives = "Bring 20 pieces of Pumpkin Pie to Marhara Goldwheat at the feasting area outside Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14061] = { id = 14061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can't Get Enough Turkey", description = "I've been cooking nonstop since before the start of the holiday, and I still can't keep up with the demand. I don't suppose I could persuade you to help with one of the dishes, could I?\n\nTurkey is hard to come by here, so if you could supply some slow-roasted turkeys, it would be a big help. If you intend to prepare them yourself, you can hunt fresh wild turkeys anywhere in the Tirisfal Glades. You should be able to buy everything else you need from any of the Pilgrim's Bounty vendors.", progress = "How's your turkey hunt going?", completion = "These turkeys are exactly what I needed. Thanks for helping me out of a tough situation.", objectives = "Bring 20 Slow-Roasted Turkeys to Ondani Greatmill outside Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14062] = { id = 14062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Forget The Stuffing!", description = "Keeping these tables stocked can be overwhelming! I've got to make the cranberry chutney while keeping my eye on the sweet potatoes, and making sure the pies don't burn.\n\nI think I've got everything covered. No, wait, I'm forgetting something. The stuffing! Oh, no. There won't be time to get another batch of stuffing started before everything else is done. Would you be willing to help me out? It shouldn't take long to buy or make some stuffing and you can buy the ingredients right here.", progress = "Were you able to get that stuffing?", completion = "Perfect timing! I wouldn't be able to serve the feast without spice bread stuffing.", objectives = "Bring 20 Spice Bread Stuffing to Ondani Greatmill outside Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14063] = { id = 14063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mutiny, Mon!", description = "Now for my favorite part of any mutiny: the killin'! For pirates, it doesn't matter who's supposed to be in charge, only who's in control of the ships. Anchored on the east end of this island is the Maiden's Dagger, Cap'n Garvey's old flagship. He left his most trusted officer in charge: Alicia Cuthbert. Once we take her out, the ship is ours, and so's the sea.\n\nI'll get the men onto the boats. I need you to board the Dagger and blow this horn from on deck - that'll be our signal to board. Yar!", progress = "Is that the Maiden's Dagger I see weighing anchor in the distance? Did you have anything to do with that?", completion = "So Tony is running the show there now? Good! We need more pirates like him in these waters. He's a real businessman.\n\n<Dizzywig rubs his hands together greedily.>\n\nSpeaking of business, I suppose I owe you a cut. Would you be interested in insuring any of your new loot? You never know what can happen in a town like this...", objectives = "Use the Pirate Signal to summon Tony Two-Tusk and his crew to the Maiden's Dagger. Help him to defeat Alicia Cuthbert below decks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14064] = { id = 14064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharing a Bountiful Feast", description = "You've not celebrated Pilgrim's Bounty properly until you've eaten your fill at a Bountiful Table.\n\nPlease, sit down, feast, and try everything! You can move from chair to chair yourself, or ask others at the table to pass you some of their food.\n\nOnce you eat enough of every dish, you'll be infused with the Spirit of Sharing.", progress = "Did you eat enough at a Bountiful Table?", completion = "What a feast, hmmm?\n\nI'm so glad you could celebrate the spirit of Pilgrim's Bounty with us.", objectives = "Eat five helpings of every food at a Bountiful Table until you gain the Spirit of Sharing. Bountiful Tables can be found in most major cities and towns.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14065] = { id = 14065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharing a Bountiful Feast", description = "You've not celebrated Pilgrim's Bounty properly until you've eaten your fill at a Bountiful Table.\n\nPlease, sit down, feast, and try everything! You can move from chair to chair yourself, or ask others at the table to pass you some of their food.\n\nOnce you eat enough of every dish, you'll be infused with the Spirit of Sharing.", progress = "Did you eat enough at a Bountiful Table?", completion = "What a feast, hmmm?\n\nI'm so glad you could celebrate the spirit of Pilgrim's Bounty with us.", objectives = "Eat five helpings of every food at a Bountiful Table until you gain the Spirit of Sharing. Bountiful Tables can be found in most major cities and towns.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14066] = { id = 14066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate the Wreckage", description = "Not long ago, a shipment of silver was stolen en route from here to Crossroads. It was meant as payroll to the guards, and we want that silver back.\n\nI'll ask around here for clues, but I want you to investigate the scene of the crime. Head west and look for a crashed caravan wagon just north of the road between here and Crossroads. Find out who took our silver and get it back!", completion = "This Horde caravan was not merely robbed. It was savagely brutalized. Crates of supplies have been ripped apart by sharp claws. The wagon has been demolished. The food has been eaten and the silver is gone, and yet useful supplies have been left behind...", objectives = "Find the wrecked caravan near the road between Ratchet and Crossroads and search the area for clues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14067] = { id = 14067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stolen Silver", description = "It's clear that these raptors acted alone to steal the Horde's silver.\n\nIt's time to teach these beasts a lesson.", progress = "You look roughed up, {class}. Did you tussle with the thieves?", completion = "<Gazrog opens the lockbox and begins counting up the silver while you relate your story.>\n\nWhat!? Raptors? Just the raptors? Assaulting our caravans and looting them? Perhaps they are as intelligent as the rumors say. As if we didn't have enough problems, now we've got to deal with brainy lizards with a lust for coin.\n\nHere, {name} - you've earned a share of the rescued silver. Thank you.", objectives = "Kill 8 Sunscale Ravagers, 4 Sunscale Scytheclaws, and locate the Stolen Silver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14068] = { id = 14068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waptor Twapping", description = "Waptor twapping can be wough, but I've designed new waptor twaps that ewiminate much of the wisk.\n\nSet the twap on the gwound and it will scweech wike a waptor, luwing one into the twap.\n\nWhen a waptor steps on my waptor twap, it'll shwink down so that it's wess dangewous. It's wewwy easy! I would do it myself but wecentwy I wan acwoss King Weapercwaw.", progress = "Where's the wittle waptors?", completion = "Hooway! You twapped the waptors I was wooking for! Now we will twain them for twolls to wide to swaughter the Awwiance!", objectives = "Use Kala'ma's \"Waptor Twap\" to capture 5 Wittle Waptors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14069] = { id = 14069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good Help is Hard to Find", description = "I've failed! I tried to meet our Kaja'Cola quotas, but you know troll slaves these days. Good help is hard to find!\n\nI think your personal touch is called for. Go show 'em what happens to slackers. If all else fails, a shock from the battery on your Goblin All-In-1-Der Belt should do the trick. Adjust their attitudes and the rest will fall in line.\n\nKaja'Cola production must continue or the Trade Prince will have all of our heads!", progress = "A good start, sir, but might I suggest that you may want to make an example of a few more?", completion = "I couldn't have done better myself. In fact, I didn't.\n\nI'm sure that in no time at all we'll all be talking about the great and powerful, and may I add extremely wealthy, Trade Prince {name}!", objectives = "Adjust the attitudes of 8 Defiant Trolls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14070] = { id = 14070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do it Yourself", description = "We need to send a message to several deadbeats. Of course, they're hiding out in Drudgetown, the scum. I know how you hate going into the slums, boss-<man/lady>, but what can we do?\n\n<Sassy rifles through some paperwork.>\n\nI have all of the names right here.\n\nMight I suggest a little 'personal visit'? A couple of strategic beatdowns will send a message to the other debtors AND your competition.\n\n{name} is not a goblin to be trifled with!", completion = "A complete success if I do say so myself, sir! Your debtors will think twice now about not paying up!\n\n<Sassy taps her pencil against her lower lip for a moment, deep in thought.>\n\nPerhaps we should increase interest rates on loans across the board?", objectives = "Beat down Bruno Flameretardant, Frankie Gearslipper, Jack the Hammer, and Sudsy Magee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14071] = { id = 14071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rolling with my Homies", description = "{name}, you're about to host the corporate party to end all corporate parties. My research says that if you're seen having a good time at the party, your promotion quotient will skyrocket and explode!\n\nSo, with that in mind, might I suggest that you take your new company hot rod out for a spin?\n\nGo pick up your friends. Just remember me on the way up when it all comes together and you're the new Trade <Prince/Princess>, okay?", progress = "The party's almost ready. How was your trip to town?", completion = "Well done, sir. You all look very good riding around in the hot rod. I'm sure you made quite an impression on the citizenry.", objectives = "Drive the Hot Rod around and pickup your friends: Ace, Gobber, and Izzy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14072] = { id = 14072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flushing Out Verog", description = "Regthar Deathgate sent me here to observe the centaur activity, but the leader of this group is hard to pin down. I've discovered that his name is \"Verog the Dervish,\" but his whereabouts are a mystery.\n\nCan you help me do some digging? I know that \"Centaur Intelligence\" sounds like an oxymoron, but their camps are often littered with important communications. Search the centaur tents all around the Stagnant Oasis here and bring me back some info.", progress = "Search those tents, {name}. Try to ignore the stench.", completion = "Good work, {name}. Did you look through these? They're barely legible - more like angry graffiti than war plans. Hatred, jealousy, rage, personal conflicts - it's a wonder Verog can keep these centaur from killing each other, much less form them into an army.\n\nWe can use this to our advantage.", objectives = "Gather 4 pieces of Centaur Intelligence from around the Stagnant Oasis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14073] = { id = 14073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deathgate's Reinforcements", description = "{name}! Your reputation among the Horde grows. I've been hearing reports from both the Forgotten Pools and the Stagnant Oasis that you've been a real bane to our centaur foes. Well done, indeed.\n\nRegthar Deathgate is in charge of our operations against the centaur all over the Northern Barrens. He could use a bold {class} like yourself to bolster his forces. Report to him at his outpost along the road west of here and aid him in any way he requires.", completion = "Ah, I've heard about your work, {class}. Your timing is fortunate - I've got a major offensive in the works.", objectives = "Report to Regthar Deathgate at his outpost west of the Crossroads in Northern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14074] = { id = 14074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Leg Up", description = "The Argent Crusade dispatched a fast ship carrying tallstrider meat and other supplies for us here at the tournament grounds, but it never arrived. Scouts reported seeing it attacked by the Kvaldir, fearsome vrykul raiders who roam the seas.\n\nThey've slain the crew and taken the cargo to an island called Hrothgar's Landing. If you look to the north, you can see it shrouded in the mist. Would you help us in recovering the stolen supplies? Without those tallstrider legs, we'll soon be out of food.", progress = "Were you able to recover any of the missing supplies?", completion = "These look a little worse for wear, but they're still edible. The crusaders will be glad to hear that we've managed to recover some of the ship's cargo.", objectives = "Recover 10 Stolen Tallstrider Legs for Narasi Snowdawn at the Argent Tournament Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14075] = { id = 14075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble in the Mines", description = "We've got trouble down in the Kaja'mine again, boss. The tunneling worms have returned and they're literally eating away at the Kajaro Trading Company's profits!\n\nKaja'mite mining is down, which is negatively impacting our production of Kaja'Cola!\n\nI tried calling the exterminator, but he's fled with the last payment we made to him.\n\nDo you think you could head into the three mines and take care of it? I'd help but I still haven't attended the cartel-mandated fighter training seminar.", progress = "I don't know, boss. I'm still getting reports of worms eating all of the kaja'mite in the mines.\n\nYou should head back down there and take care of them.", completion = "I say good riddance to those pests!", objectives = "Slay 6 Tunneling Worms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14076] = { id = 14076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breakfast Of Champions", description = "Now that the coliseum is complete, the Argent Crusade has asked us to help look after the creatures that champions will be fighting.\n\nThe giant jormungar have perhaps the strangest diet; they grow strong by eating the eggs of their own kind and the best eggs come from deep jormungar.\n\nTake this drum to the Foot Steppes in central Storm Peaks and play them near the snow mounds you see there.  Rouse the deep jormungar, kill them, and gather their egg sacs.", progress = "Were you able to get those eggs? Those worms will start eating their handlers if they're not fed soon.", completion = "Well done, {name}. I'll take these to the Argent Crusade's keepers right away. They'll have no choice but to acknowledge that we're doing far more than the Sunreavers to keep the coliseum running smoothly.", objectives = "Acquire 4 Jormungar Egg Sacs and bring them to Savinia Loresong at the Argent Tournament Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14077] = { id = 14077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Light's Mercy", description = "I've been listening to Confessor Paletress speak, and I must tell you, her words have given me much to consider. It is not enough to fight beside the crusaders; we must take up their mission.\n\nOff the north coast is Hrothgar's Landing, where the seagoing Kvaldir have overrun an old tuskarr settlement and slain the villagers. Take this book and read the rites for the dead near the corpses of the villagers. It will allow their spirits to escape the mists engulfing the island and find peace.", progress = "Have you seen to the spirits of the slain Tualiq villagers?", completion = "<Narasi accepts the prayer book from you.>\n\nThank you. The book was a gift from Confessor Paletress herself. She would  be honored to know that you have used it to bring tranquility to the slain.", objectives = "Use the Confessor's Prayer Book to perform last rites for 8 Slain Tualiq Villagers and then return to Narasi Snowdawn at the Argent Tournament Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14078] = { id = 14078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lockdown!", description = "What are you still doing here, citizen?  Haven't you heard?  The city's under complete lockdown.\n\nGo see Lieutenant Walden -- he'll give you further directions for evacuation.", completion = "Deep claw marks run through the man's corpse.", objectives = "Find Lieutenant Walden in the northwestern end of the Merchant Square.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14079] = { id = 14079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn to Ride in Elwynn Forest", description = "This pamphlet advertising riding training and mount purchases was sent from Randal Hunter.\n\nRandal can be found at Elwynn Forest's Eastvale Logging Camp, along the road east out of Stormwind.", progress = "Ah, you received my letter? Good.", completion = "So, shall we begin your Apprentice Riding training?", objectives = "Return the pamphlet to Randal Hunter at Eastvale Logging Camp in Elwynn Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14080] = { id = 14080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop The Aggressors", description = "The Kvaldir, fearsome vrykul raiders, have disrupted our shipments and murdered the tuskarr inhabitants of an island to the north, renaming it Hrothgar's Landing. If they are allowed to get a foothold there, there is no doubt that we will be their next target.\n\nThe crusade's forces have their hands full dealing with the Scourge, and we must defend the tournament grounds. Fly north from the grounds until you reach the island and take on the Kvaldir before they can destroy anything else.", progress = "Have you shown the Kvaldir that we will not let them threaten us?", completion = "Your actions have shown that we stand as one with the Argent Crusade, while the Sunreavers are too busy preening to take up their blades.", objectives = "Narasi Snowdawn at the Argent Tournament Grounds wants you to kill 10 Kvaldir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14081] = { id = 14081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn to Ride in the Eversong Woods", description = "This pamphlet advertising riding training and mount purchases was sent from Perascamin.\n\nPerascamin can be found at Thuron's Livery, southeast of the Shepherd's Gate leaving Silvermoon City.", progress = "Ah, you received my letter? Good.", completion = "So, shall we begin your Apprentice Riding training?", objectives = "Return the pamphlet to Perascamin at Thuron's Livery in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14082] = { id = 14082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn to Ride at the Exodar", description = "This pamphlet advertising riding training and mount purchases was sent from Aalun.\n\nAalun can be found at the entrance to the Exodar on Azuremyst Isle.", progress = "Ah, you received my letter? Good.", completion = "So, shall we begin your Apprentice Riding training?", objectives = "Return this pamphlet to Aalun outside the Exodar on Azuremyst Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14083] = { id = 14083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn to Ride in Dun Morogh", description = "This pamphlet advertising riding training and mount purchases was sent from Ultham Ironhorn.\n\nUltham can be found at the Amberstill Ranch in Dun Morogh, found along the road east out of Ironforge.", progress = "Ah, you received my letter? Good.", completion = "So, shall we begin your Apprentice Riding training?", objectives = "Return the pamphlet to Ultham Ironhorn at Amberstill Ranch in Dun Morogh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14084] = { id = 14084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn to Ride in Dun Morogh", description = "This pamphlet advertising riding training and mount purchases was sent from Binjy Featherwhistle.\n\nBinjy can be found at Steelgrill's Depot, just northeast of Kharanos in Dun Morogh.", progress = "Ah, you received my letter? Good.", completion = "So, shall we begin your Apprentice Riding training?", objectives = "Return the pamphlet to Binjy Featherwhistle at Steelgrill's Depot in Dun Morogh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14085] = { id = 14085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn to Ride in Darnassus", description = "This pamphlet advertising riding training and mount purchases was sent from Jartsam.\n\nJartsam can be found at the Cenarion Enclave in Darnassus.", progress = "Ah, you received my letter? Good.", completion = "So, shall we begin your Apprentice Riding training?", objectives = "Return the pamphlet to Jartsam at the Cenarion Enclave in Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14086] = { id = 14086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn to Ride in Orgrimmar", description = "This pamphlet advertising riding training and mount purchases was sent from Kildar.\n\nKildar can be found in Orgrimmar's Valley of Honor.", progress = "Ah, you received my letter? Good.", completion = "So, shall we begin your Apprentice Riding training?", objectives = "Return the pamphlet to Kildar in Orgrimmar's Valley of Honor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14087] = { id = 14087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn to Ride in Mulgore", description = "This pamphlet advertising riding training and mount purchases was sent from Kar Stormsinger.\n\nKar can be found in Mulgore's Bloodhoof Village.", progress = "Ah, you received my letter? Good.", completion = "So, shall we begin your Apprentice Riding training?", objectives = "Return the pamphlet to Kar Stormsinger at Bloodhoof Village in Mulgore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14088] = { id = 14088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn to Ride in Durotar", description = "This pamphlet advertising riding training and mount purchases was sent from Xar'Ti.\n\nXar'Ti can be found at Sen'jin Village in southern Durotar.", progress = "Ah, you received my letter? Good.", completion = "So, shall we begin your Apprentice Riding training?", objectives = "Return the pamphlet to Xar'Ti at Sen'jin Village in southern Durotar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14089] = { id = 14089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn to Ride in Tirisfal Glades", description = "This pamphlet advertising riding training and mount purchases was sent from Velma Warnam.\n\nVelma can be found at Brill in Tirisfal Glades.", progress = "Ah, you received my letter? Good.", completion = "So, shall we begin your Apprentice Riding training?", objectives = "Return the pamphlet to Velma Warnam at Brill in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14090] = { id = 14090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormok Wants His Snobolds", description = "Two of my men have already been killed trying to confine the magnataur called Gormok the Impaler, yet the creature still rages. It howls for hours about being without its favorite snobold.\n\nIf the Argent Crusade didn't wish to use this monster in the coliseum, I'd slay it myself. Perhaps it's time to bring the beast its playthings. Take this net and travel to Garm's Bane in southeast Storm Peaks. It's just northeast of K3. Capture some of those snobolds and pray to the Light you've found the right one.", progress = "Have you managed to round up those snobolds yet? Gormok's anger shows no signs of lessening.", completion = "The sooner we get these stinking things out of my sight and into their cage, the faster my mood will improve. I wish the Argent Crusade had given the Sunreavers the care of this creature. They're enough alike that they ought to be able to understand each other.", objectives = "Use the Weighted Net to capture 8 Snowblind Followers and bring them to Savinia Loresong at the Argent Tournament Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14091] = { id = 14091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something's Amiss", description = "The lieutenant appears to have died from severe wounds.  The prince might want to hear this news.\n\nYou hear the sound of fighting coming from the market.", completion = "It's you again.  Looks like you're not one to hide in the face of danger.  Very well, then.", objectives = "Return to Prince Liam Greymane in the Merchant Square.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14092] = { id = 14092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breakfast Of Champions", description = "Now that the coliseum is complete, the Argent Crusade has asked us to help look after the creatures that champions will be fighting.\n\nThe giant jormungar have perhaps the strangest diet; they grow strong by eating the eggs of their own kind and the best eggs come from deep jormungar.\n\nTake this drum to the Foot Steppes in central Storm Peaks and play them near the snow mounds you see there. The sound will rouse the deep jormungar. Kill them, collect their egg sacs, and return to the tournament grounds.", progress = "Were you able to get those eggs? The jormungar are going to get nasty if they don't get fed.", completion = "I'll let the crusaders know that you've just returned with a fresh load of food while the Silver Covenant was sitting on its heels.", objectives = "Acquire 4 Jormungar Egg Sacs and bring them to Tylos Dawnrunner at the Argent Tournament Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14093] = { id = 14093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Hell Breaks Loose", description = "Worgen!  My father had warned me that Archmage Arugal's creations had run amok.\n\nBut where are they coming from?\n\nI suppose it doesn't matter.  Help us make quick work of them.  We'll show them what we Gilneans are made of!", progress = "Have the {race} been dealt with?", completion = "It's no use, {name}!  They're not letting up.", objectives = "Prince Liam Greymane wants you to slay 6 Rampaging Worgen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14094] = { id = 14094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salvage the Supplies", description = "Listen, {name}.  We can't let our supplies get destroyed.\n\nWith Gilneas walled off from the outside world, we won't last through winter if we lose much more of our stock.\n\nPlease help me salvage what you can.", progress = "Have you salvaged the supplies, {name}?", completion = "Excellent!  I'll make sure these get taken to a safe place.", objectives = "Salvage 4 Supply Crates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14095] = { id = 14095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Identifying the Remains", description = "A whole tooth from a dead Kraken is a rare find indeed.  Crusader Silverdawn will want to see this.", progress = "What have you found, Champion?", completion = "I knew that Kraken was not a match for the likes of you.  Without that Kraken disrupting those boats, those Kvaldir will have no choice but to retreat.  Great job, Champion!", objectives = "Take the Kraken Tooth to Crusader Silverdawn as proof of your victory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14096] = { id = 14096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You've Really Done It This Time, Kul", description = "Crusader Kul has gone and gotten himself into trouble again, only this time he's not alone. When he saw the cultists making camp at Deathspeaker's Watch, west of the tournament grounds, Kul gathered the aspirants for an assault.\n\nWithout reinforcements, Kul and his followers were easily captured. I have no doubt that the cult will sacrifice the prisoners unless we can mount a rescue. Any of those cultists could carry keys to the black cages. Find the keys and free Kul and the captive aspirants.", completion = "Thanks to you, Kul and the aspirants will live to fight the Scourge again. That's far from the first time someone's had to save Kul from himself. My only hope is that the crusaders can find a better outlet for his enthusiasm than allowing him to impart all of his bad habits to impressionable young aspirants.", objectives = "Rescue Kul the Reckless and 4 Captive Aspirants from Deathspeaker's Watch and return to Narasi Snowdawn at the Argent Tournament Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14097] = { id = 14097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get That Merchant Out of Here!" }
quests[14098] = { id = 14098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evacuate the Merchant Square", description = "The civilians aren't safe here anymore.  Not even inside their homes.\n\nWe're doing our best to stop the worgen from getting indoors, but their numbers are too great.\n\nHelp us by evacuating the civilian homes.  My father's army in the prison district will be able to better protect them.", progress = "Have you succeeded, {name}?", completion = "Good job, {name}.  Thanks to you, many Gilneans will live to see another day.", objectives = "Evacuate 3 Civilian Homes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14099] = { id = 14099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Royal Orders", description = "It's time for you to leave, {name}.  Go to the Military District with the other civilians.\n\nCheck in with Gwen Armstead when you cross the bridge to the southeast... see if everyone's okay.\n\nI will stay here with the guards and cover the civilians' retreat.\n\nGo now.  That is an order!", completion = "We're all fine here.  A little shaken... but alive.", objectives = "Speak to Gwen Armstead in the Military District to the southeast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14100] = { id = 14100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relic of the Earthen Ring", description = "You have progressed far in your training, {name}. Now that you have mastered the four basic elements, you must strive to keep all four in balance. There is a practical benefit to this discipline - with practice, you may carry only a single relic instead of all four totems.\n\nSpeak to Gotura Fourwinds at the Valley of Wisdom in Orgrimmar, and hone your mastery of the elements.", sourceObjective = "Bring your four totems to Gotura Fourwinds in Orgrimmar.", progress = "Hmmm, what brings you to seek the aid of the Earthen Ring?", completion = "Ah, you've mastered the four totems. You should be proud of your accomplishments so far, young {race}, but this is only the beginning of your journey.\n\nHere, accept this gift from the Earthen Ring. Carry this relic with you and you will have the power of all four elements at your command.\n\nContinue your training, friend. Grave challenges are ahead for this world - I can hear it in the wind and feel it in the rumblings of the earth. We must be prepared for the worst.", sourceObjectiveStatus = "unverified-source-field" }
quests[14101] = { id = 14101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drottinn Hrothgar", description = "The Kvaldir, seafaring vrykul who raid ships and coastal settlements, have overrun a tuskarr  island across the strait to the north. Their leader is a veteran raider, Drottinn Hrothgar, who seeks to control these seas.\n\nWith him in power, our shipments and troop transports will never be safe. We will be stranded here at the Lich King's mercy.\n\nTake this captured Kvaldir war horn to the circle of tuskarr statues on the northeastern part of Hrothgar's Landing and use it to challenge the Kvaldir leader.", progress = "We cannot allow Drottinn Hrothgar's men to continue their assault on our ships and our men.", completion = "The defeat of the drottinn will set the kvaldir to fighting amongst themselves, buying us time to use our advantage. The crusade and the tournament are in your debt, champion.", objectives = "High Crusader Adelard at the Argent Tournament Grounds wants you to defeat Drottinn Hrothgar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14102] = { id = 14102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistcaller Yngvar", description = "The Kvaldir have returned to the coasts of Northrend and if left unchecked, they will prevent our supplies and reinforcements from arriving. One of them, known as Mistcaller Yngvar, has taken up residence in a cave on the western side of Hrothgar's Landing. There, he manipulates the mists to conceal the Kvaldir and  the sea beasts they command.\n\nTake this charm and travel across the strait north of the tournament grounds, to Hrothgar's Landing. Find the mistcaller's cave and use the charm to reveal him.", progress = "Have you defeated Mistcaller Yngvar and disrupted his rituals?", completion = "You have bought us valuable time to move against the Kvaldir and free the seas of these pests. Once again, the Argent Crusade is in your debt.", objectives = "High Crusader Adelard at the Argent Tournament Grounds wants you to kill Mistcaller Yngvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14103] = { id = 14103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titanium Powder", progress = "Hello {name}!  Do you have anything to trade?", completion = "Wonderful!  Another batch of powder!\n\nJust between us jewelcrafters, I've been making hand over fist selling \"pure titanium\" jewelry to the local Dalaran mages.  Even with their superior intellect, they aren't particularly savvy with their gold.  If you get more, I'll be here." }
quests[14104] = { id = 14104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ornolf The Scarred", description = "Ornolf the Scarred is a fearsome raider renowned among his Kvaldir brethren for raiding and capturing ships. From aboard Bor's Fury, he and his crew attack our ships and steal our goods.\n\nOrnolf and his men are among those who slaughtered the inhabitants of a tuskarr island to the north and renamed it Hrothgar's Landing. His ship sits at anchor at the eastern end of the island's harbor. Take this captured banner and display it on his ship to provoke him into facing you in battle.", progress = "Have you dealt with Ornolf the Scarred?", completion = "Ornolf's crew will want to avenge their leader, but without him, they will be easier to defeat. We must live to carry out our mission, to see Icecrown rid of the Scourge and other evils.", objectives = "High Crusader Adelard at the Argent Tournament Grounds wants you to kill Ornolf the Scarred.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14105] = { id = 14105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deathspeaker Kharos", description = "The Cult of the Damned has redoubled its efforts to see us destroyed. They have grown bold and are massing their strength at Deathspeaker's Watch on the ridge west of the tournament grounds.\n\nThe ruthless Deathspeaker Kharos has his men fortifying their positions, preparing to unleash all of the cult's weapons.\n\nMy men are preparing themselves and the valiants to defend the grounds, but I want champions like you, {name}, to lead our efforts to blunt the attack. Find Deathspeaker Kharos and slay him.", progress = "Have you defeated the leader of the cult's attack?", completion = "You are truly an example to all who have gathered beneath our banner, {name}. Together, we will show the Scourge that we will not be defeated.", objectives = "High Crusader Adelard at the Argent Tournament Grounds wants to you kill Deathspeaker Kharos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14106] = { id = 14106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Na Kada's Quest Test" }
quests[14107] = { id = 14107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate Of The Fallen", description = "The Argent Crusade is hardly the first force to challenge the Lich King. Our enemy turns spirits of the fallen against us.\n\nTheir spirits wander the Valley of Fallen Heroes, southwest of the grounds and between Aldur'thar and the Ironwall Rampart. The area is littered with discarded soul crystals, used by the Scourge to control the spirits. Gather those soul crystals and use them with this Light-blessed relic to bestow the blessing of peace upon the spirits. They have more than earned their rest.", progress = "Have you brought peace to the spirits of the fallen heroes?", completion = "You have done our fallen brethren a great service and spared us the need to face them again on the field of battle. As our campaign against the Scourge progresses, I find myself thinking about my own fate.\n\nShould I fall, {name}, I would want someone like you to do for me what you have done for the spirits of the fallen this day. I could not bear the thought of forcing my own brothers to slay me again and again.", objectives = "Crusader Silverdawn wants you to bring peace to 6 Fallen Hero's Spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14108] = { id = 14108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Kraken!", description = "The Sunreavers and Silver Covenant sent ships north to engage the Kvaldir at Hrothgar's Landing, but were intercepted and detained by a Kvaldir Raiding vessel.  To make matters worse, the Kvaldir have found a way to call forth the dreaded Kraken that lives beneath the North Sea.  If anyone on board is to get out alive, that Kraken must be driven away and the Kvaldir's summoning ritual ... disrupted.\n\nCrusader, take these spears and an Argent Hippogryph will take you to the battle.", progress = "Have you driven away the Kraken yet?  Hurry, Crusader! There isn't much time.", completion = "Crusader, you may have bought those sailors just enough time to escape,  Maybe next time, those Silver Covenant and Sunreavers will listen before running head first at the enemy.", objectives = "Crusader Silverdawn wants you to mount an Argent Hippogryph, throw 8 Flaming Spears at the North Sea Kraken and take out 6 Vrykul Deepcallers.\n\nYou can find the Argent Hippogryphs right outside the Argent Crusade tent at the Tournament Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14109] = { id = 14109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The New You", description = "A new outfit? You don't say! There's quite a buzz surrounding your party. Everyone who's anyone on the island is going to be there.\n\nWell, happy shopping. Swindle Street has some of the best bargains anywhere!", progress = "Do you have it all, {name}? I can't wait to see it on you!\n\nYou bought the good stuff, right?", completion = "Oh, you are going to look so fine, but not as gorgeous as me! You're going to replace the Trade Prince any day now at the rate you're going!\n\nI can't wait to not have to work anymore! You're going to buy me everything that I want, right babe?\n\nLet me have all that stuff and I'll help you get into it right before the party.", objectives = "Buy some Shiny Bling from Gappy Silvertooth, a Hip New Outfit from Szabo, and some Cool Shades from Missa Spekkies on Swindle Street.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14110] = { id = 14110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The New You", description = "A new outfit? You don't say! There's quite a buzz surrounding your party. Everyone who's anyone on the island is going to be there.\n\nWell, happy shopping. Swindle Street has some of the best bargains anywhere!", progress = "Do you have it all? I can't wait to see it on you!\n\nMmm hmm!", completion = "Oh yeah, you're going to look hot! You're going to replace the Trade Prince any day now at the rate you're going!\n\nI can't wait to be a kept man!\n\nLet me have all that stuff and I'll help you get into it right before the party.", objectives = "Buy some Shiny Bling from Gappy Silvertooth, a Hip New Outfit from Szabo, and some Cool Shades from Missa Spekkies on Swindle Street.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14111] = { id = 14111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relic of the Earthen Ring", description = "You have progressed far in your training, {name}. Now that you have mastered the four basic elements, you must strive to keep all four in balance. There is a practical benefit to this discipline - with practice, you may carry only a single relic instead of all four totems.\n\nSpeak to Farseer Eannu near the Great Forge in Ironforge. He will help you hone your mastery of the elements.You will learn:", sourceObjective = "Bring your four totems to Farseer Eannu in Ironforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[14112] = { id = 14112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Do You Feed a Yeti, Anyway?", description = "The crusaders have captured a yeti that they're calling Icehowl. He's to be a participant in the coliseum battles and we've been asked to help with his training and upkeep.\n\nThe crusaders weren't fond of my suggestion that we feed the beast surplus Sunreavers. The creature has a predilection for shark meat, so I want you to fly down to the Silver Blade, floating in the strait to the north. Get some fresh chum from one of the buckets on the boat, then spread it in the water to attract sharks.", progress = "I hope you have something to feed Icehowl, otherwise I really will start bringing Sunreavers down to his cage.", completion = "I'm glad we've gotten that done. It's not the most glorious task in the world, but when we partnered with the Argent Crusade, we promised to do all they asked of us without complaint. Of course, the same cannot be said of the Sunreavers.", objectives = "Savinia Loresong at the Argent Tournament Grounds wants you to bring her 3 pieces of North Sea Shark Meat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14113] = { id = 14113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Life of the Party", description = "Oh my gosh, babe! Everyone is here! Who cares about some stupid dragon?\n\nWe setup the party around the pool. Sounds like they're having a great time. You are going to look so good!\n\nWhy don't you head over to the pool and keep everyone entertained? I'll join you in a moment... I just have to slip into something even more amazing!", progress = "How's the party going?\n\nYou look amazing! So dashing and handsome, sir!", completion = "Very nicely done, sir. The party appears to have been a smashing success!\n\nEr... what's that?", objectives = "Put on your Awesome Party Ensemble (Cool Shades, Hip New Outfit, and Shiny Bling) and then head over to the party at the KTC Headquarters pool to entertain 10 Kezan Partygoers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14114] = { id = 14114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The New You (Tracking Event)" }
quests[14115] = { id = 14115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pirate Party Crashers", description = "Oh my gosh! Pirates!\n\n{name}, there are Southsea pirates crashing your party!\n\nYou have to get in there and do something about this or your career, and any chance of you being the next Trade <Prince/Princess>, is going to be ruined!", progress = "Was that all of them? I know that I saw a lot rushing in!", completion = "Phew, that was close, boss. Unfortunately, I'm the bearer of more bad news.\n\nPlease don't shoot me....", objectives = "Kill 12 Pirate Party Crashers in order to save your career.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14116] = { id = 14116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Uninvited Guest", description = "While you were dealing with the pirates, I noticed the Trade Prince slip upstairs. He's up on the balcony at the top of the stairs.\n\n{name}, I think he's the one that sent the pirates.\n\n<Sassy cringes.>\n\nYou'd better get up there A.S.A.P.! You wouldn't want to keep him waiting.", completion = "Well, well, well, if it isn't my wayward protege, Mr. {name}.\n\nI'm hurt and disappointed. You didn't send me an invitation to your little party out there. Sorry about the crashers... you know how pirates can be.\n\nSo, shall we get down to business?", objectives = "Speak with Trade Prince Gallywix upstairs at the KTC Headquarters main building on Kezan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14117] = { id = 14117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eyes of Ashenvale", description = "Our enemies abound, {class}, even here at our very doorstep. The night elves have reinforced Talrendis Point in an attempt to stop our advance into Ashenvale. As we speak, their scouts patrol the nearby hills, reporting every movement to and from these gates.\n\nWe must remove these eyes of Ashenvale.\n\nGo. Your prey stalks all around these gates, especially to the east. Slay the scouts who shadow us!", completion = "Excellent. As their scouts fail to report in, Talrendis will feel the terror they've tried in vain to inflict on us.", objectives = "Kill 8 Talrendis Scouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14118] = { id = 14118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venison for the Troops", description = "As we chew up the resources of this land for our war machines, we deprive the local animals of their homes. If they are to die anyway, we should not allow that meat to go to waste. Not when the maw of Orgrimmar gapes open, hungry.\n\nKill the weakened mosshoof stags that remain in this area and collect their meat for our peons and grunts.", progress = "You smell of fresh kill, {class}.", completion = "Meat - and lots of it! Well done. This will keep bellies full as we build our arsenal.", objectives = "Collect 15 Slabs of Venison from Weakened Mosshoof Stags.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14120] = { id = 14120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bazillion Macaroons?!", description = "You're an extremely ambitious young goblin, {name}. Maybe a little too ambitious for your own good. I see a lot of myself in you when I was your age.\n\nI have a proposition. You might have noticed that Mount Kajaro is exploding thanks to your dragon. Everyone on Kezan is going to die!\n\nBut, if you bring me a bazillion macaroons before my yacht leaves the island, I'll make sure that you're one of the lucky few to escape.\n\nIf you want to live, you better hurry and figure out how to get me my moolah!", completion = "A bazillion macaroons?!?! Where are we going to get that kind of moolah?\n\n<Sassy thinks a moment.>\n\nUm... did the Trade Prince say anything about letting me escape with you on his yacht?", objectives = "Speak with Sassy Hardwrench at KTC Headquarters on Kezan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14121] = { id = 14121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Robbing Hoods", description = "We're all going to die!!!\n\n<You slap Megs to calm her down.>\n\nSorry about that, <Mr./Ms.> {name}. Okay, we need to find a way to get a lot of moolah quickly.\n\nThere are reports of the Trade Prince sending hired looters into the streets.\n\nYou could take the hot rod out there and run them down, snatching the loot that they've illegally stolen. There wouldn't be anything wrong with that, right?", progress = "Were you able to steal a whole bunch of stolen loot?", completion = "Wow, you really did it?! Well, they had it coming, I guess.\n\nThat's an awful lot of loot. Do you think it's enough to get you a spot on the Trade Prince's yacht?\n\nAre you going to be able to bring anyone with you? I don't make too much working in marketing.", objectives = "Use your Hot Rod to run over 12 Hired Looters, collecting 12 Stolen Loots in the process.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14122] = { id = 14122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Bank Heist", description = "All of your assets have been frozen and the First Bank of Kezan is out of business!\n\nYou need an awful lot of moolah, boss. I think you're going to have to go break your own money out of the bank! The different widgets in your Goblin All-In-1-Der belt should be enough to crack the vault.\n\nI just hope that you've been saving for a rainy day like I always told you to do. You might have noticed... it's raining hot liquid magma!!!", progress = "Did you get it? Did you crack the safe and get your personal riches out of the bank?", completion = "Hey, you have been saving! I'm so proud of you!\n\n<Sassy counts all of your macaroons.>\n\nUm, boss... this isn't nearly enough.", objectives = "Crack the vault at the First Bank of Kezan to retrieve your Personal Riches.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14123] = { id = 14123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waltz Right In", description = "There's only one way we're going to get a bazillion macaroons: stealing from the rich!\n\nThat slime, the Trade Prince, has stolen all kinds of antiques and expensive art. It's time to take them back and give them to the needy... mainly us!\n\nHobart left behind a cap he was working on. It's a disguise that'll make you look like one of Gallywix's mooks. All you have to do is waltz right in to his Villa to the west and 'procure' the items.\n\nJust watch out for his pigs who can smell through the disguise!", progress = "You got the goods, boss?", completion = "Oh, wow! These are worth a fortune.\n\n<Slinky eyes everything with a practiced, greed-filled eye.>\n\nI just hope that the Trade Prince doesn't notice them when you hand them over with the rest of your wealth....", objectives = "Obtain Maldy's Falcon, The Goblin Lisa, and The Ultimate Bomb.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14124] = { id = 14124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liberate the Kaja'mite", description = "<Sir/Ma'am>, we need tons of moolah to pay the Trade Prince and get off Kezan! Well, tons of it is just waiting for the taking down there in the Kaja'mine!\n\nThese are the last known deposits of kaja'mite anywhere. This is the raw stuff that made us the genius tinkerers and alchemists we are today. If that's not worth a bazillion macaroons, I don't know what is!\n\nTake some of my kablooey bombs and blowup the deposits. Then, pick up the chunks.\n\nJust watch out for the rebellious trolls!", progress = "How much Kaja'mite do you have?", completion = "Nicely done, sir, nicely done! That's a fortune you have there in your bags.\n\nWith all of that, I bet the Trade Prince will let all of us come along on his yacht!", objectives = "Collect 12 Kaja'mite Chunks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14125] = { id = 14125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "447", description = "We're close, but we still don't have enough macaroons. But, I've got a plan: we're going to collect on the headquarters insurance policy!\n\nHope you don't mind, but I filled the place with the leftover fireworks from your party. All you have to do is go in there and sabotage things.\n\nMight I suggest the faulty generator, the leaky stove, and the flammable bed? Then, come back outside and use the control panel to send in the gasbot.\n\nIt's a foolproof plan!", completion = "This is nothing. You should see Bilgewater Port... the whole thing is going up in flames!\n\nFine, fine, I don't have time to inspect this place. Here's the moolah from the Bilgewater Cartel's insurance policy.\n\nI've got to find a way off the island! Good luck, {name}!", objectives = "Overload the Defective Generator, Activate the Leaky Stove, Drop a Cigar on the Flammable Bed, and use the Gasbot to set KTC Headquarters ablaze!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14126] = { id = 14126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Life Savings", description = "We've got all of the moolah that we need. There's only one thing left to do now, boss: get you to the Trade Prince's yacht. It's about to leave port!\n\nWe're gonna have to hurry. Hop in, 'cause I'm driving!", progress = "Oh, {name}, it's you. What an unexpected surprise.", completion = "Congratulations, you just made it. I see that you've brought me all that I asked for, including your hot rod.\n\n<The Trade Prince flashes an evil grin.>\n\nA bazillion macaroons couldn't have been easy to come by. I'm now the wealthiest, most powerful, {race} on all of Azeroth!\n\nTOO BAD FOR YOU THAT I'M CHANGING THE TERMS OF OUR DEAL!\n\nYou're now my slave. Get below deck and take a turn shoveling coal. Next stop, Azshara!\n\nMuahahahahahahahaha!", objectives = "Hand over your Life Savings to Trade Prince Gallywix aboard the Trade Prince's Yacht on Kezan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14127] = { id = 14127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Highborne?", description = "The wax seal on these orders has been freshly broken. You can't read the carefully-penned night elven script, but a small hand-drawn map indicates the nearby ruins. Underneath the map, written in a different language entirely, are a series of runes penned in a metallic, shimmering ink.\n\nAg'tor will no doubt want to see this important piece of intelligence.", progress = "You found something on one of the bodies, you say? Give it here!", completion = "<Ag'tor squints at the parchment, turning it in the light.>\n\nNo, I can't make sense of it either, but I don't like what I see. Are these arcane runes?\n\nI'll need you to deliver this to an expert.", objectives = "Deliver the Scout's Orders to Ag'tor Bloodfist at the rear gate to Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14128] = { id = 14128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Highborne?", description = "Our blood elven allies have been examining the ruins marked on this map, and can likely understand this mysterious script. Seek out the one called Malynea Skyreaver. She conducts her research from the Orgrimmar Rocketway Exchange just north of here - it's part of the new goblin transit system that snakes across this land. Quickly, now!", progress = "I trust this interruption is in regards to something important?", completion = "What? Give that here, this instant! Ag'tor is correct, these are arcane runes. They're scouting out magical sites? Experimenting with the arcane arts? This is a marked departure from thousands of years of night elven history.\n\nHmph! The idea that they will achieve any competence in this field - even those who once counted themselves among the highborne - is absurd.\n\n<Malynea puts aside the scroll dismissively, but her face is furrowed with concern.>", objectives = "Deliver the Scout's Orders to Malynea Skyreaver at the Orgrimmar Rocketway Exchange.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14129] = { id = 14129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runaway Shredder!", description = "I've been trying to impress our new Horde allies with our legendary goblin efficiency, but in hindsight automating the shredders was a bad idea. Now they're mindless killing machines, rampaging over the countryside. Don't get me wrong - that kind of thing has its place - but for the time being I need a brave {class} to help me get these things under control.\n\nIt's easy. Automated shredders, like all machines, must first be beaten into submission. Afterwards, seize the controls and I'll radio you instructions.", completion = "<Labor Captain Grabbit's voice crackles over the radio.>\n\nHey {name}! Are you reading this?\n\nPiloting that sucker is easy. Push the pedals for your pedal controls and, ah, move the levers for your lever controls. Got it?", objectives = "Attack one of the Runaway Shredders near the rear gates of Orgrimmar and hop inside once it's been significantly damaged.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14130] = { id = 14130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friends Come In All Colors", description = "My brothers and I are being hunted.\n\nOur sire was recently killed and the black dragonflight seeks to rout those of us that still live. I'm here to find Azuregos and take him to safety, if only he would let it be that easy.\n\nAzuregos doesn't make many friends, and his taste in them tends to be a bit... unique. The only one I know of here is a murloc named Ergll. You should be able to find him on the coast northeast of here.\n\nDo whatever it takes to find Azuregos and send him to me.\n\nPlease hurry.", completion = "Hello there! A new friend! So glad to meet you. My name is Ergll. The g is silent.", objectives = "Locate Ergll on the coast of the Ruins of Arkkoran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14131] = { id = 14131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Pick-me-up", description = "Azuregos... Azuregos. Azy? The dragon? We're friends, definitely! Taught me to speak. Said he liked my hue... kinda colorist, eh?\n\nDon't remember where he went. Mmm... maybe something to help my memory?\n\nI plant Kawphi plants all over the beach. They like sand. Kinda weird.\n\nCould you go collect some?", progress = "So tired, it's hard to concentrate.", completion = "Beautiful beans! They smell absolutely delicious, don't they?", objectives = "Collect 10 Kawphi Beans from the plants in the Ruins of Arkkoran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14132] = { id = 14132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's Just Rude!", description = "I'd share if they asked. They just go clickity-claking up my kawphi plants. So rude! You should teach them a lesson.\n\nDumb Makrinni.", completion = "Too mean? Naw, not too mean. They deserved it.\n\nI don't gum up their plants. Not ever.", objectives = "Kill 10 Makrinni in the Ruins of Arkkoran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14133] = { id = 14133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Way to a Mage's Heart", description = "Now that you've finished his errands, it's time for Ergll to tell you about Azuregos. Talk to him and see if you can get any useful leads on Azuregos' possible location.", objectives = "Ask Ergll about Azuregos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14134] = { id = 14134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captain's Logs", description = "Now that you've got that thing under control, let's gather up the lumber I was supposed to be collecting. Otherwise these orcs are going to build a catapult out of ME!\n\nFresh lumber should be stockpiled all around the area. Use the shredder to collect all you can.", progress = "How's the wood processing going? You should see what that thing does to broccoli!", completion = "Great! You've loaded the shredder to capacity. You're getting pretty handy with that thing...", objectives = "Use the Reprogrammed Shredder to collect 6 piles of Azshara Lumber. If you lose your shredder, another can be attacked and reprogrammed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14135] = { id = 14135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up a Tree", description = "Hold still a second, I'm going to bring your main buzzsaw controls online.\n\nNight elven snipers from Talrendis have been hiding in the trees, taking potshots at my workers. I want you to take care of those snipers... by first taking care of those trees. Look for Azshara saplings east of the main gates. Your shredder will know what to do. Chop to it!", completion = "Great work, {name}! That's how we took care of business back on Kezan.", objectives = "Use the shredder's buzzsaw to cut down Azshara Saplings, and kill 9 Talrendis Snipers as they emerge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14136] = { id = 14136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue at Sea", description = "The Kvaldir have set up camp at Hrothgar's Landing, the small island to the North.  We sent Captain Aerthas Firehawk to the area, but they ran into a Kvaldir Raiding party heading to the Tournament Grounds!  The Firehawk is now under attack by the raiders and is vastly outnumbered. Get out there and show those Kvaldir why attacking the Sunreavers is a poor plan indeed. \n\nThe Firehawk is between Hrothgar's Landing to the north and the Tournament Grounds, on the western side of The Sea Reaver's Run.", progress = "Have you defended The Firehawk?", completion = "Great job, Champion.  The fight continues, but now the Kvaldir know that we do not tolerate such attacks.", objectives = "Girana the Blooded at the Argent Tournament Grounds would like you to kill 8 Kvaldir Berserkers and 3 Kvaldir Harpooners aboard The Firehawk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14137] = { id = 14137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Class Training (Tracking Event)" }
quests[14138] = { id = 14138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Care of Business", description = "With all of the troubles down in the Kaja'mine, Foreman Dampwick's been going crazy trying to find you. He said something about some 'defiant trolls'.\n\nThe kaja'mite that our trolls are mining is critical ingredient in Kaja'Cola. That bubbly stuff is making us a fortune, and it's going to get you a promotion to Trade <Prince/Princess>!\n\nBut first, we have to get production flowing again. You'll find the foreman to the east. Here, give him this as an incentive to get his act together.", progress = "Um... everything's going great. Yeah.\n\nWhat's that?", completion = "A gift from Sassy? I hope it's a bonus!", objectives = "Deliver Sassy's Incentive to Foreman Dampwick at KTC Headquarters on Kezan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14139] = { id = 14139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phase 1 Complete (Tracking Event)" }
quests[14140] = { id = 14140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop The Aggressors", description = "The Kvaldir, fearsome vrykul raiders, have disrupted our shipments and murdered the tuskarr inhabitants of an island to the north, renaming it Hrothgar's Landing. If they are allowed to get a foothold there, there is no doubt that we will be their next target.\n\nThe crusade's forces have their hands full dealing with the Scourge, and we must defend the tournament grounds. Fly north from the grounds until you reach the island and take on the Kvaldir before they can destroy anything else.", completion = "Your actions have shown that we Sunreavers are far better allies to the Argent Crusade than the Silver Covenant and it is we who will be triumphant.", objectives = "Giranan the Blooded at the Argent Tournament Grounds wants you to kill 10 Kvaldir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14141] = { id = 14141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormok Wants His Snobolds", description = "Two of my men have already been killed trying to confine the magnataur called Gormok the Impaler, yet the creature still rages. It howls for hours about being without its favorite snobold.\n\nIf the Argent Crusade didn't wish to use this monster in the coliseum, I'd slay it myself. Perhaps it's time to bring the beast its playthings. Take this net and travel to Garm's Bane in southeast Storm Peaks. It's just northeast of K3. Capture some of those snobolds and pray to the Light you've found the right one.", progress = "Have you managed to round up those snobolds yet? Gormok's anger shows no signs of lessening.", completion = "The sooner we get these stinking things out of my sight and into their cage, the faster my mood will improve. I wish the Argent Crusade had given the Silver Covenant the care of this creature. They're going to have to get their hands dirty when the battle for Icecrown Citadel starts and I have a feeling they'll prove fragile and fussy allies.", objectives = "Use the Weighted Net to capture 8 Snowblind Followers and bring them to Tylos Dawnrunner at the Argent Tournament Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14142] = { id = 14142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You've Really Done It This Time, Kul", description = "Crusader Kul has gone and gotten himself into trouble again, only this time he's not alone. When he saw the cultists making camp at Deathspeaker's Watch, west of the tourney grounds, Kul gathered the aspirants for an attack.\n\nThey were easily captured, and now Kul languishes in a cage on the platform in the camp. I am sure that the cult will sacrifice the prisoners unless we can rescue them. Any of those cultists could carry keys to the black cages. Find the keys and free Kul and the captive aspirants.", completion = "Kul will live to embarrass himself again. That's far from the first time someone's had to save Kul from himself. With examples like him, it's no wonder most of the aspirants are taking up the habits of the Silver Covenant.", objectives = "Rescue Kul the Reckless and 4 Captive Aspirants from Deathspeaker's Watch and return to Girana the Blooded at the Argent Tournament Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14143] = { id = 14143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Leg Up", description = "The Argent Crusade dispatched a fast ship carrying tallstrider meat and other supplies for us here at the tournament grounds, but it never arrived. Scouts reported seeing it attacked by the Kvaldir, fearsome vrykul raiders who roam the seas.\n\nThey've slain the crew and taken the cargo to an island called Hrothgar's Landing. If you look to the north, you can see it shrouded in the mist. Would you help us in recovering the stolen supplies? Without those tallstrider legs, we'll soon be out of food.", progress = "Were you able to recover any of the missing supplies?", completion = "These look a little worse for wear, but they're still edible. The crusaders will be glad to hear that we've had some success. Maybe we can give the half-eaten ones to the Silver Covenant. That would make my day.", objectives = "Recover 10 Stolen Tallstrider Legs for Girana the Blooded at the Argent Tournament Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14144] = { id = 14144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Light's Mercy", description = "I've been listening to Confessor Paletress speak, and I must tell you, her words have made me think. We fight beside the crusaders, but we can learn from them, too.\n\nOff the north coast is Hrothgar's Landing, where the seagoing Kvaldir have overrun an old tuskarr settlement and slain the villagers. Take this book and read the rites for the dead near the corpses of the villagers. It will allow their spirits to escape the mists engulfing the island and find peace.", progress = "Have you seen to the spirits of the slain Tualiq villagers?", completion = "<Girana accepts the prayer book from you.>\n\nThank you. We don't always see eye-to-eye with the crusaders, but I've learned a lot from Confessor Paletress in my time here.", objectives = "Use the Confessor's Prayer Book to perform last rites for 8 Slain Tualiq Villagers and then return to Girana the Blooded at the Argent Tournament Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14145] = { id = 14145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Do You Feed a Yeti, Anyway?", description = "The crusaders have captured a yeti that they're calling Icehowl. He's to be a participant in the coliseum battles and we've been asked to help with his training and upkeep.\n\nThe crusaders weren't fond of my suggestion that we feed some Silver Covenant members to the beast. The creature prefers shark meat, so I want you to fly down to the Crimson Dawn, floating in the strait to the north. Get some fresh chum from one of the buckets on the boat, then spread it in the water to attract sharks.", progress = "I hope you have something to feed Icehowl, otherwise I really will start bringing Silver Covenant members down to his cage.", completion = "I'm glad we've gotten that done. It's not the most glorious task in the world, but when we partnered with the Argent Crusade, we promised to do all they asked of us without complaint. Of course, the same cannot be said of the Silver Covenant.", objectives = "Tylos Dawnrunner at the Argent Tournament Grounds wants you to bring him 3 pieces of North Sea Shark Meat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14146] = { id = 14146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defend the Gates!", description = "Egah - what's going on?\n\n<Screams, shouts, and the roar of combat fills the radio.>\n\n{name}! Get back here right away. Hurry back to the gates - we're under attack!\n\nHelp us fend off the invaders. I'm arming your grenade launcher!!", objectives = "Labor Captain Grabbit needs you to rush back to the Rear Gate of Orgrimmar to slay 20 Night Elf Raiders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14151] = { id = 14151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cardinal Ruby", description = "The Cardinal Ruby is said to be the finest gem in all of Northrend.  It sparkles like a crystal rose under the sun.\n\nBefore I teach you this recipe, I ask that you perform five epic gem transmutes to prepare your mind.  You can do any you like, and even do the same transmute many times.\n\nReturn to me when you are truly ready.", completion = "Very good, {name}.\n\nNow, the trick is to align the facets just right...", objectives = "Linzy Blackbolt in Dalaran wants you to successfully transmute 5 epic gems with your alchemy skill. Acceptable transmutes include Ametrine, Eye of Zul, Dreadstone, King's Amber, and Majestic Zircon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14152] = { id = 14152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue at Sea", description = "Champion, Captain Wavecrest and her ship were sent north to disrupt the Kvaldir in Hrothgar's Landing when they were intercepted by a Kvaldir raiding party headed to the Tournament Grounds. Unfortunately, the Kvaldir far outnumber the crew on board and are slowly taking over the ship.\n\nWe need you to go north to The Wavecrest in The Sea Reaver's Run, between the Tournament Grounds and Hrothgar's Landing and help the crew fend off the attack.  You should see the ship on the east side of the pass.", progress = "Have you helped fend off the Kvaldir attack?", completion = "It seems things are worse than we initially thought.  You still made a valiant effort and saved many of The Wavecrest's crew's lives.", objectives = "Head out to The North Sea and kill 8 Vrykul Berserkers and 3 Vrykul Harpooners attacking The Wavecrest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14153] = { id = 14153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Life of the Party", description = "Oh wow, baby! Everyone is here! Who cares about some stupid dragon?\n\nWe setup the party around the pool. Sounds like they're having a great time already. You are going to look so fine!\n\nWhy don't you head over to the pool and keep everyone entertained? I'll join you in a moment... I just have to grab my stuff.", completion = "Very nicely done, ma'am. The party appears to have been a smashing success!\n\nEr... what's that?", objectives = "Put on your Awesome Party Ensemble (Cool Shades, Hip New Outfit, and Shiny Bling) and then head over to the party at the KTC Headquarters pool to entertain 10 Kezan Partygoers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14154] = { id = 14154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By the Skin of His Teeth", description = "One of those mangy fleabags got Dempsey real good.  We cannot move him until we stabilize his bleeding.\n\nGive us a hand holding back these mongrels.  A couple of minutes is all we need, <brother/sister>!", progress = "Getting there!  Careful or we'll lose him!", completion = "We did it, {name}.  Thanks to you a good man has survived.", objectives = "Hold back the worgen atop the Gilneas City Prison for 2 minutes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14155] = { id = 14155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arborcide", description = "How's that shredder holding up? I think I can bring your emergency power supplies online - that'll recharge you when you're wounded.\n\nListen, these night elves are being strengthened by an ancient of war who's taken root just west of the gates. He's a big, giant tree. You know what to do! Take him out!\n\nYou were made for this!!", completion = "You did it, {name}! The invaders have pulled back. And they told me I was crazy for installing a grenade launcher on a woodchipper...\n\nGreat work with the Shredder. With an impressive showing like that right here on the Warchief's doorstep, the Horde can't doubt what goblin technology can do for them. I owe you a big thanks!", objectives = "Use the Shredder to destroy the Talrendis Ancient. Emergency Backup Shredders are available at the Orgrimmar Rear Gate if you lose yours.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14156] = { id = 14156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Man on the Inside", description = "If the king wants to rescue Lord Crowley and his band of traitors, then we will follow his orders.\n\nIt is just as well... one of my men was assigned to infiltrate Crowley's group in prison and it most certainly would be good to find out if he's survived this incident.\n\nApproach Sean Dempsey discretely... you do not want to give away his position among Crowley's men.  They might prove to be more dangerous to his life than the worgen.", sourceObjective = "Find Sean Dempsey on the rooftop of the Gilneas City Prison.If the king wants to rescue Lord Crowley and his band of traitors, then we will follow his orders.\n\nIt is just as well... one of my men was assigned to infiltrate Crowley's group in prison and it most certainly would be good to find out if he's survived this incident.\n\nApproach Sean Dempsey discretely... you do not want to give away his position among Crowley's men. They might prove to be more dangerous to his life than the worgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14158] = { id = 14158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phase 6 Complete (Tracking Event)" }
quests[14159] = { id = 14159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rebel Lord's Arsenal", description = "The arsenal Crowley speaks of is in the cellar of a building just west of here.\n\nIt is unnerving that artillery was smuggled inside the city by my enemies, yet it might end up saving Gilnean lives today.\n\nFind Josiah Avery and requisition the rebel artillery.  We will put the weapons to good use.", completion = "Don't look at me!  Leave me alone!", objectives = "Speak to Josiah Avery at the Military District in Gilneas City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14160] = { id = 14160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Writ of Merit", description = "This fine parchment lists a great many accomplishments, achieved by {name}, in the tradition of jewelcrafting.\n\nReturn this writ to Timothy Jones in Dalaran for a proper reward.", objectives = "Deliver the Writ of Merit to Timothy Jones in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14161] = { id = 14161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basilisk Bashin'", description = "We moved this whole mountain to strip mine the minerals below. But what we didn't take into consideration were the subterranean basilisks that are now, uh, terranean. You look like you've got some initiative - go in there and kill some of those nuisances and I'll dip into our petty cash fund for you.", completion = "Good, good. One less nuisance to worry about.", objectives = "Kill 10 Greystone Basilisks in the Mountainfoot Strip Mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14162] = { id = 14162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Horzak", description = "You've done a bangup job getting our lumber operations in order. But word on the wire is that we're falling under our stone quota. You'd think if we could move mountains, we could gather up a few rocks...\n\nWell, that's not my problem, but maybe you can make it yours. Report to Horzak Zignibble up ahead at the Orgrimmar Rocketway Exchange. See if you can't help him straighten out his operations. Just follow the road northeast and find him in the rocketway tower.", completion = "You're here to help? Excellent! Here, sign this indemnity waiver. And here, this noncompete clause. Let's get you started!", objectives = "Find Horzak Zignibble at the Orgrimmar Rocketway Exchange in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14163] = { id = 14163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Isle of Conquest", description = "As we get closer to victory in Icecrown, it's become more apparent that our armies are going to have to deal with the Horde before they can deal with the Lich King.\n\nThe elite guard known as the Kor'kron has been deployed to block our advance in the Isle of Conquest.  The isle is of vital strategic importance, {name}.  See to it that our lads prevail!", objectives = "Win an Isle of Conquest battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14164] = { id = 14164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Isle of Conquest", description = "Victory in Northrend will be ours soon... but not until we obtain a foothold in Icecrown to transport and supply our forces.\n\nThe Isle of Conquest is an ideal location.  It is easily defensible and rich in resources.  The Alliance have reached the same conclusion and have sent the Seventh Legion to wrest control of it from our forces.\n\nGo, {name}, and ensure that the Horde prevails at any cost!", objectives = "Win an Isle of Conquest battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14165] = { id = 14165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stone Cold", description = "Workers act like it's their job to complain. If it isn't the backbreaking labor, the long hours, or the low pay, it's being turned to stone by basilisks. It's always something!\n\nBut I'm thinking maybe this whole workers-to-stone business could be a big moneymaker for me. What if those guys are now high-quality stone? My whiny employees could be worth more to me as luxury building materials than a source of labor! Grab a stonified mountainfoot miner and haul him or her back to me.", progress = "Get to the strip mine, {name}, and get me a sample of one of my former workers!", completion = "Well well, let's take a look at what we got here...\n\n<Horzak examines the shattered remains of the poor petrified miner.>\n\nBah! Crumbly! Useless. Wouldn't even make a good countertop. My miners may be mediocre workers, but they make lousy bricks.\n\n<Sigh>. Well, I suppose we should re-fleshify these guys so I can get some return on my investment.", objectives = "Collect a stonified Mountainfoot Miner from the Mountainfoot Strip Mine and bring him or her back to Horzak Zignibble at the Orgrimmar Rocketway Exchange.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14166] = { id = 14166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grateful Dead", description = "It's good to visit with friends and family again, though I may have overdone it... I've already eaten everything they made for me!\n\nMight I trouble you for some more of that delicious Bread of the Dead? I'd be most grateful...\n\nChapman there sells the recipe, I think.", progress = "You don't have any Bread of the Dead, do you?", completion = "Ah, more delicious Bread of the Dead, thank you!\n\nPlease, take this in return... a little something fun for the holiday.", objectives = "Acquire some Bread of the Dead and give it to the Cheerful Dalaran Spirit in Dalaran's graveyard.\n\nUse an Orange Marigold to see the otherwise invisible spirit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
