quests[14173] = { id = 14173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grateful Dead", description = "It's good to visit with friends and family again, though I may have overdone it... I've already eaten everything they made for me!\n\nMight I trouble you for some more of that delicious Bread of the Dead? I'd be most grateful...\n\nChapman there sells the recipe, I think.", progress = "You don't have any Bread of the Dead, do you?", completion = "Ah, more delicious Bread of the Dead, thank you!\n\nPlease, take this in return... a little something fun for the holiday.", objectives = "Acquire some Bread of the Dead and give it to the Cheerful Scryer Spirit in Shattrath's graveyard.\n\nUse an Orange Marigold to see the otherwise invisible spirit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14174] = { id = 14174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grateful Dead", description = "It's good to visit with friends and family again, though I may have overdone it... I've already eaten everything they made for me!\n\nMight I trouble you for some more of that delicious Bread of the Dead? I'd be most grateful...\n\nChapman there sells the recipe, I think.", progress = "You don't have any Bread of the Dead, do you?", completion = "Ah, more delicious Bread of the Dead, thank you!\n\nPlease, take this in return... a little something fun for the holiday.", objectives = "Acquire some Bread of the Dead and give it to the Cheerful Forsaken Spirit in Undercity's graveyard.\n\nUse an Orange Marigold to see the otherwise invisible spirit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14175] = { id = 14175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grateful Dead", description = "It's good to visit with friends and family again, though I may have overdone it... I've already eaten everything they made for me!\n\nMight I trouble you for some more of that delicious Bread of the Dead? I'd be most grateful...\n\nChapman there sells the recipe, I think.", progress = "You don't have any Bread of the Dead, do you?", completion = "Ah, more delicious Bread of the Dead, thank you!\n\nPlease, take this in return... a little something fun for the holiday.", objectives = "Acquire some Bread of the Dead and give it to the Cheerful Orc Spirit in Orgrimmar's graveyard.\n\nUse an Orange Marigold to see the otherwise invisible spirit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14176] = { id = 14176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grateful Dead", description = "It's good to visit with friends and family again, though I may have overdone it... I've already eaten everything they made for me!\n\nMight I trouble you for some more of that delicious Bread of the Dead? I'd be most grateful...\n\nChapman there sells the recipe, I think.", progress = "You don't have any Bread of the Dead, do you?", completion = "Ah, more delicious Bread of the Dead, thank you!\n\nPlease, take this in return... a little something fun for the holiday.", objectives = "Acquire some Bread of the Dead and give it to the Cheerful Tauren Spirit in Thunder Bluff's graveyard.\n\nUse an Orange Marigold to see the otherwise invisible spirit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14177] = { id = 14177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grateful Dead", description = "It's good to visit with friends and family again, though I may have overdone it... I've already eaten everything they made for me!\n\nMight I trouble you for some more of that delicious Bread of the Dead? I'd be most grateful...\n\nChapman there sells the recipe, I think.", progress = "You don't have any Bread of the Dead, do you?", completion = "Ah, more delicious Bread of the Dead, thank you!\n\nPlease, take this in return... a little something fun for the holiday.", objectives = "Acquire some Bread of the Dead and give it to the Cheerful Troll Spirit in Orgrimmar's graveyard.\n\nUse an Orange Marigold to see the otherwise invisible spirit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14178] = { id = 14178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Arathi Basin", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle of Arathi Basin that demands immediate reinforcements.\n\nReturn to me with news of victory, {name}.  We cannot allow the Horde scum to secure the resources that are rightfully ours!", objectives = "Win an Arathi Basin battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14179] = { id = 14179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Eye of the Storm", description = "The fight against the Horde knows no boundaries, {name}.  Even in Outland, territorial disputes and old hatreds are enough to tip the scales in favor of war.\n\nGo into the Eye of the Storm and make sure the Alliance prevails in Outland just like it has in Azeroth.", objectives = "Win an Eye of the Storm battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14180] = { id = 14180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Silverwing Sentinels fight to protect the forest in Warsong Gulch.  We aid them, not because we're tree-lovers, but because the forest forms a natural protective barrier for Alliance territory.\n\nTheir need is greater today than it's ever been.  We need to deploy reinforcements right away unless we want to see Ashenvale annexed to the Barrens!", objectives = "Win a Warsong Gulch battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14181] = { id = 14181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Arathi Basin", description = "Arathi Basin is on the verge of being lost to Alliance forces.  We must send reinforcements at this very moment or all our efforts will have been in vain.\n\nDo not delay, {class}, go to Arathi Basin and crush the enemy.  Victory to the Horde!", objectives = "Win an Arathi Basin battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14182] = { id = 14182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Eye of the Storm", description = "We will fight and crush the enemy wherever we find them.  Azeroth, Outland, the place makes no difference.\n\nWe cannot allow the Alliance to establish superiority in the Eye of the Storm.  Take the battle to them today... tomorrow it might be too late!", objectives = "Win an Eye of the Storm battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran,  or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14183] = { id = 14183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Alliance is an insidious enemy, {name}.  They claim to defend the Ashenvale forests to justify their acts of aggression against our territories in the Barrens.\n\nToday we have an opportunity to drive the enemy from our lands once and for all.  Go to Warsong Gulch and take back what is rightfully ours!", objectives = "Win a Warsong Gulch battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14184] = { id = 14184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Time Has Passed", description = "<Weakly, Furien beckons you near and struggles to speak.>\n\nCareless... I was shot down by Alliance fire...\n\nYou must... inform my sister.\n\nTake my mount, {race}... he'll bring you to her...\n\n<Furien expires.>", completion = "What!?\n\nFurien!! My brother is no more?\n\nThey must pay! All of them!", objectives = "Furien at Tethris Aran wants you to ride his Dragonhawk to Furien's Post and inform his sister, Cerelia of his death.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14185] = { id = 14185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Riding Trainer Advertisement (40)" }
quests[14186] = { id = 14186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Riding Trainer Advertisement (60)" }
quests[14187] = { id = 14187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Riding Trainer Advertisement (70)" }
quests[14188] = { id = 14188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avenge Furien!", description = "This cannot be!\n\nMy dear brother - slain by Alliance scum!\n\nThey must be made to suffer, {race}! Find a way to bring them pain! I shall not rest until it is so...\n\nFurien had been researching ancient artifacts in the eastern regions before his death. Speak to Sorrem. Perhaps he can direct you in my brother's footsteps.", completion = "Furien's passing is... regrettable.\n\nI shall do all that I can to assist you in avenging his death.", objectives = "Cerelia wants you to speak with Sorrem at Furien's Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14189] = { id = 14189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Translation", description = "It is true that Furien dedicated his last days to a special research project. What that was, he would not share with me.\n\nFortunately, I was able to recover his journal, but it's written in a code that I cannot decipher.\n\nPerhaps there is a clue to its translation in the region to the east where he spent his time.\n\nTake the journal, {class}, and speak with Narimar when you are ready to investigate this mystery.", completion = "Comparing the characters on the ancient tablet to those in Furien's journal, it is clear that there is a distinct correlation.", objectives = "Sorrem wants you to find the Ancient Tablets.\n\nSpeak to Narimar at Furien's Post to ride to where Furien was known to study.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14190] = { id = 14190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Perfect Prism", description = "There's got to be a way to reverse the basilisks' stonification. Those irritating night elf saboteurs who have been lurking around my mine must know something we don't. They seem to be immune to the gaze of the beast!\n\nI want you to find out their secret, {name}. Pick off a few of the Talrendis saboteurs skulking about in the rear of the strip mine and get a sample of whatever charm or ding-dong they're wearing to give them immunity. Radio me from the main forge building once you're successful.", progress = "<Strange goblin speakers hiss and crackle.>", completion = "<Zignibble's voice squawks over the speakers.>\n\nIs that you, {name}? Still alive? You aren't trashing my explosive stockpiles are you?\n\nHmmm... you say you found a clear crystal pendant. That makes sense. A perfect prism would refract the gaze of the basilisk. Maybe we can use this to our advantage. Time to drop some science!", objectives = "Acquire a Crystal Pendant from a Talrendis Saboteur in the Mountainfoot Strip Mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14191] = { id = 14191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furien's Footsteps", description = "You can decipher bits and pieces of the text, but it will require extensive study before Furien's work becomes coherent.\n\nFor now, as you look off to the northeast, you think you can make out some of the ruins depicted in the journal.\n\nFrom what you can tell, these ruins seem to have been of some significance to Furien's research.", completion = "It is clear to you now that these ruins are those that Furien recorded in his journal.\n\nAfter examining the engravings upon the ruins themselves, you feel that you are able to decipher more of Furien's writings.", objectives = "The Ancient Tablets at the Shrine of Elune have directed you to visit three of the prominent ruins in Sargeron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14192] = { id = 14192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prismbreak", description = "If that prism of yours is tuned to refract a basilisk's gaze, we can use its crystal properties to reverse the process. All we need is a source of power.\n\nIn the weapons cabinet to your right, you'll find our prototype laser mining drill. I loved that thing but the near daily dismemberments got to be a real bother. Grab the laser drill and swap out the lens with that crystal of yours...", progress = "<The weapons cabinet is loaded with heinous and broken experimental devices, some of which still have goblin limbs attached. You discover the laser drill lovingly ensconced in a velvet-lined wooden case.>", completion = "<You pop out the lens assembly and slide the crystal into place. The weapon hums ominously.>", objectives = "Take the Crystal Pendant to the Weapons Cabinet in the Mountainfoot Strip Mine Headquarters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14193] = { id = 14193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nothing a Couple of Melons Won't Fix", description = "The markings on the ruins here make one thing clear: There is something special about the old fountain in the Sanctuary of Elune.\n\nIt would seem that one could expect special power from washing their face in the fountain. First, of course, there would need to be something in the ancient fountain with which to wash.\n\nPondering this problem, you spot a melonfruit at the base of a nearby tree....", completion = "After filling it with liquid from the melons, you proceed to wash your eyes from the ancient font.\n\nUpon opening your eyes, you are able to see the spirits of ancient elves, still faithfully carrying out rituals to their goddess.", objectives = "Gather 8 Melonfruit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14194] = { id = 14194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Refleshification", description = "<The nearby radio calls out to you.>\n\nHey {name}, you got that gun? Good! Don't point it directly at your eye.\n\nAim that baby at my stonified workers and the refracted light should reverse the petrification process. Or it will melt them. Whatever. Return my workers to a state of profitability! And if the refleshification process makes them crazy-go-nuts, they should be killed for insurance purposes. Horzak OUT!", progress = "Hey look, all your limbs are intact.", completion = "Ah, good. Now we can get these slackers back to work. You've earned a cut of the profits though - minus the usual company fees. Take your pick!", objectives = "Use The Refleshifier to de-stonify eight Mountainfoot Miners within the Mountainfoot Strip Mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14195] = { id = 14195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Becoming Clearer", description = "Something has changed... perhaps a side-effect of Elune's cleansing ritual.\n\nWhile it's by no means perfect yet, your understanding of the ancient language in the journal has vastly improved.\n\nThe ruins in the northern mountains of Sargeron appear to be the main focus of Furien's enthusiasm. Something there, he felt, would aid him in driving the Alliance from this region.\n\nYou close the journal determined to find this ruin and discover its secrets.", progress = "This appears to be the ruin depicted in Furien's Journal.", completion = "It is clear to you now why you were guided here.\n\nYou recognize this ancient runestone from Furien's final journal entry:\n\n\"The ancients revered the gems created by this mystical object, claiming that they were gifts from the goddess herself. It was believed that they were weapons capable of delivering them from any enemy.\"", objectives = "Furien's Journal has directed you to find the ruined Palace of Elune in northern Sargeron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14196] = { id = 14196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firestarter", description = "You are now able to understand the script in which the journal was written.\n\nAlong the runestone, it is explained that the monument's gemstones were imbued with the power to summon a firestorm.\n\nThe storm could grow to be a mighty weapon either through sustained worship of Elune, or charged by spiritual energies of the fallen.\n\nLooking down upon the newly revealed ghosts of Elune's disciples, you reason that you have neither the time, nor the inclination to worship the goddess of your enemy....", completion = "It is done! Furien's exhaustive research was not in vain.\n\nThe raging Vortex is ready to be unleashed upon your enemies at last!", objectives = "You are to create a Raging Vortex by defeating 7 Disciples of Elune in the presence of your firestorm.\n\nShould you lose your Vortex Gem, another can be obtained from the Ancient Vortex Runestone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14197] = { id = 14197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Quota to Meet", description = "Mountainfoot iron is a brittle alloy, but with the right bribes it meets goblin safety standards. Zignibble here is having trouble on the production end of things, but that doesn't change any of my deadlines. I've got a quota to fill!\n\nHead down into the Mountainfoot Strip Mine and gather up any ingots of Mountainfoot iron you find. There should be piles of it smelted and ready for shipment.", progress = "Did you get my shipment together?", completion = "Well done! When it comes to iron, always pick quantity over quality.", objectives = "Gather 20 ingots of Mountainfoot Iron from the Mountainfoot Strip Mine in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14198] = { id = 14198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rider on the Storm", description = "You cannot help but to feel a twinge of pride, having unlocked this long lost secret of the ancient worshippers of Elune.\n\nYou now possess the power to inflict great damage upon your enemy.\n\nAs it was Furien's tireless work that made this possible, it only seems right that the weapon should be unleashed upon those who took his life.\n\nThe Alliance scum at Nijel's Point shall pay for their offenses against the Horde!", completion = "Very impressive, {class}.\n\nYou completed Furien's work and rained vengeance down upon his killers.\n\nYou have brought peace to my brother's soul, and to my mind. Please accept this gift for your diligence.", objectives = "Use the Raging Vortex Gem at Nijel's Point Ruin. While commanding your firestorm, kill 40 Nijel's Point Defenders and burn 15 Nijel's Point Merchants.\n\nShould you lose your Raging Vortex Gem, you may acquire another from the Ancient Vortex Runestone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14199] = { id = 14199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: The Black Knight", description = "My counterpart, Archmage Timear, has asked me to warn you of something dire. Soon, you will be participating in the Trial of the Champions at the Argent Coliseum in Icecrown. You must beware of interference from one known only as the Black Knight.\n\nBring me a fragment of his soul that the Kirin Tor will know he is dealt with. I am told that failing to do so will be your own undoing.", objectives = "Archmage Lan'dalock in Dalaran wants you to return with a Fragment of the Black Knight's Soul.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14200] = { id = 14200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kickoff Mail Marker" }
quests[14201] = { id = 14201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Thousand Stories in the Sand", description = "The ruins around Lake Mennar, to our east, have a tale to tell. The lesser races - like those clumsy dwarves - would go after the truth with picks and shovels. <Malynea wrinkles her nose.> We'll be using more elegant methods.\n\nMy scrying magic is somewhat rusty, but with the right trinket I should be able to peer through the shrouds of time. The bones of my forefathers have long since rotted away but some of their personal treasures may remain - bring me some.", progress = "Have you gotten your hands dirty for me?", completion = "<Malynea furrows her brow and begins sifting through the artifacts you brought her.>\n\nSo the spirits of the dead still haunt those old stones, hm? Well {name}, as it happens, I'm counting on their help. Let's see what the dead have to say...", objectives = "Collect 5 Recovered Artifacts from the ruins around Lake Mennar in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14202] = { id = 14202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survey the Lakeshore", description = "All these cruddy ancient ruins have to be bulldozed if we're ever to see Azshara's full potential. Look on my map here - you see Lake Mennar, to the East? I'll tell you what I see: a future rocket fuel depot!\n\nBut we need an accurate lay of the land before we can clearcut, bulldoze, landfill, and pave over that lake. All of my surveyors have been spooked off by the oogly-boogleys haunting that area. Escort one of my Jr. grade surveyors to the area and take readings from the equipment that's been set up.", progress = "No buncha dead elves can put a stop to progress. Not on my watch!", completion = "Beautiful work! Now that we know the area better, we can tear this lake a new one.", objectives = "Escort a Goblin Surveyor to the three pieces of Surveyor's Equipment that surround Lake Mennar, and defend her while she takes readings. Another Surveyor can always be summoned with your Surveyor's Beacon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14203] = { id = 14203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waterlogged Recipe", description = "This appears to be the remains of a mixture for potent wine.  Perhaps the proprietor of One More Glass in Dalaran would be interested in it....", progress = "Wine is only as fine as the person drinking it, I always say.", completion = "This is quite a find, {name}.  I can't have you selling this to anyone else, so I'm willing to offer generously.", objectives = "Bring the Waterlogged Recipe to Christi Stockton in the Dalaran city.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14204] = { id = 14204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From the Shadows", description = "He turned into one of them... didn't he?  How do we even begin to fight an enemy that can do this to us?\n\nMy father's arsenal's certainly a good start, I suppose.\n\nWorgen are hiding in the alleys ahead.  Take one of my mastiffs to find them more easily.\n\nWe're going to need to clear the way ahead if we're going to move these cannons above ground.", progress = "Is it done yet, {name}?", completion = "Excellent.  I'll start rounding up some help to get these cannons positioned.", objectives = "Defeat 6 Bloodfang Lurkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14209] = { id = 14209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gunk in the Trunk", description = "Those ancient ruins have survived ten thousand years of wind and weather, so I brought out my biggest and bestest bulldozer to flatten 'em. I call her \"Margene.\"\n\nBut my dozer's been letting me down lately, {name}. The moment I drove her into those haunted woods, her engine seized up with a spine-chilling howl. Now my engineers tell me something's clogging her valves. Go over there and inspect Margene's engine compartment, and bring me back a sample of whatever gunk has her stalled.", progress = "Margene is one heck of a machine, isn't she?", completion = "Busted ball bearings! Look at this stuff - ugh, SMELL this stuff - my poor, poor dozer!\n\n{name}, I consider myself a goop expert and this here goop ain't natural. It's supernatural. This is ghost goop. We're going to need more than a mechanic...", objectives = "Inspect Clubnik's Dozer and collect a sample of the Ectosplatter that's gumming up the engine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14212] = { id = 14212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sacrifices", description = "You don't have to do this, {name}.  You've done more than enough already.\n\nBut if you decide to stay... I'd be a fool to turn you away.\n\nMy men have fortified their position inside the cathedral and are ready for what comes next.\n\nI'm about to head there and take as many of these flea-ridden devils with me as I can.  You're welcome to come along for the ride.", progress = "Every {race} we keep inside the city is one less {race} going after our loved ones outside.", completion = "Brace yourself, {name}.\n\nHere they come.", objectives = "Ride with Lord Darius Crowley and round up 30 Bloodfang Stalkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14213] = { id = 14213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ten Pounds of Flesh", description = "According to Furien's Journal, this ancient brazier was placed here for the performing of sacrifices.\n\nAs far as you can make out from the entry, a blessing is bestowed upon the being who places the flesh of Elune's enemies on the brazier's burning embers.\n\nLooking around, you determine that the satyrs who now possess this region would likely qualify.", progress = "The brazier silently awaits an offering.", completion = "The divine brazier indiscriminately endows you with a blessing.", objectives = "You are to collect 10 pieces of Satyr Flesh from the various Satyrs in Sargeron, and place them on Elune's Brazier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14214] = { id = 14214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Message to Greymane", description = "It's time, {name}.  We'll take it from here.\n\nTell King Greymane that my father's arsenal will be at his disposal.  There's more than enough firepower here to blow the worgen from here to the north sea.", completion = "I knew Crowley would come through.  His weapons will be more than useful to us.", objectives = "Speak to King Genn Greymane in the Military District.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14215] = { id = 14215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Memories of the Dead", description = "The runes on this ring you found are still legible: it was given to \"Kalytha\" when she was granted admission to the Academy. With the right spell or two, this personal trinket of hers is the gateway to her soul.\n\nTake the ring back to Lake Mennar. Kalytha's spirit should now be visible to you on the shore of the lake. Touch her and the ring will allow you to see the world as she sees it, forever reliving her final hours. Probe her mind, {name}! Speak to the others and learn the secrets of Lake Mennar...", completion = "You reel as the spirit's vision fades, relieved to once again feel the earth beneath your feet and the comforting rhythm of your own quickened heart.", objectives = "Take Kalytha's Ring to the shores of Lake Mennar. Touch the Spirit of Kalytha to relive her memories. Speak to the other spirits until you've learned the secret of Lake Mennar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14216] = { id = 14216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystery of the Sarcen Stone", description = "Before she died, Kalytha was charged with burying something at the bottom of the lake, a powerful artifact that the archmages of Mennar spent their last moments creating. No doubt Malynea Skyreaver will want to see the artifact, presuming it still exists. You resolve to search the bottom of Lake Mennar for the Sarcen Stone.", progress = "Did you discover anything at the lake? You're soaking wet.", completion = "A Sarcen stone? That's the stuff of legend - let me see that!\n\n{name}, Sarcen stones are used to redirect the ley lines of magical energy. You realize what this means? The mages of Mennar weren't staying behind out of misguided loyalty. They sacrificed their lives in order to create this artifact in an attempt to draw energy away from the portal through which the demons were flooding Azeroth. They were buying time for the rest of the world to fight back! History never recorded their deeds. What a discovery!", objectives = "Retrieve the Sarcen Stone from the bottom of Lake Mennar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14217] = { id = 14217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Satyrical Offerings", description = "You find it most amusing to think that this ancient relic is bestowing upon you a blessing meant for your enemies.\n\nYou determine to make as much as you can of this unintentional gift.", progress = "The brazier silently awaits an offering.", completion = "The divine brazier indiscriminately endows you with a blessing.", objectives = "You are to collect 10 pieces of Satyr Flesh from the various Satyrs in Sargeron, and place them on Elune's Brazier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14218] = { id = 14218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By Blood and Ash", description = "The time has come, {name}.  If we're going to put a dent in their numbers, the time is now.\n\nWe have the position.\n\nWe have the firepower.\n\nAll that remains to be seen is whether we have the courage... and I sure don't see a coward standing in front of me.", progress = "We must take out as many of them as we can, {name}.", completion = "You've done well, {name}.  You've done more than could be asked of any Gilnean.\n\nWe're running low on ammunition.  It's time to regroup inside now.", objectives = "Slay 80 Bloodfang Stalkers using the Rebel Cannons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14219] = { id = 14219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Hilt!", description = "You immediately recognize this statue from a sketch in Furien's Journal.\n\nThough the words associated with the entry elude you, the sketch seems self-explanatory. After battle, the enemies' weapons were to be cast upon the basin in exchange for a divine gift of some sort.\n\nAs you ponder this ritual, the glint of steel catches your eye from a nearby weapon rack....", progress = "The statue stands expectantly.", completion = "With the ritual completed, you are awarded a divine gift.\n\nYou can't help but wonder what Elune would think of someone such as you receiving one of her boons.", objectives = "You are to collect 20 Satyr Sabers from the weapon racks and various satyrs in the region, then place them upon the statue, Elune's Handmaiden.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14220] = { id = 14220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Is the End" }
quests[14221] = { id = 14221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Surrender, Sometimes Retreat", description = "We had enough ammunition to carry on the civil war for another month.  Yet the worgen's numbers are such that we're nearly spent.\n\nWe don't want to be caught out here in the open when that happens.  Fall back inside the cathedral and report to the boss.  I'm sure old Crowley will know what to do next.", completion = "We've given them everything we have... yet still they come.  Do not worry, {name}.  We'll slay many more before today is over.", objectives = "Speak to Lord Darius Crowley inside the Light's Dawn Cathedral.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14222] = { id = 14222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Stand", description = "We've got a good chokepoint here, {name}.  Feel free to say a prayer if that's your sort of thing.\n\nTake courage and let's kill these mutts.", progress = "We can do this, {name}.", completion = "They... they've stopped coming.\n\nNo, {name}.  That's not a good thing.", objectives = "Kill 8 Frenzied Stalkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14223] = { id = 14223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peace of Mind", description = "We are a forward post, charged with monitoring potential adversaries. Once the Horde launches its Desolace campaign, our work here will ensure that nothing takes us by surprise.\n\nRecently, one of our scouts was caught and sacrificed by the Burning Blade at their stronghold to the east. Since then, we've been assaulted with threats and taunts from a Burning Blade wretch named Kohor.\n\nTheir days here are numbered, but I will pay handsomely for that one to be silenced now!", progress = "So, is it done, {class}?", completion = "It is done.\n\nSorrem should be able to sleep in peace now that Kohor's threats have been silenced.", objectives = "Sorrem at Furien's Post wants you to kill Kohor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14225] = { id = 14225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You'll Know It When You See It", description = "With his dying breath, Kohor mentioned the summoning of a demon that could threaten the entire region.\n\nHe may have been bluffing, but that's not a chance worth taking.\n\nThis cannot wait for the Horde's invasion of Desolace to take shape. You must scour Thunder Axe Fortress for clues and bring an end to this potential threat.", progress = "The Burning Blade must not be allowed to succeed with their plan!", completion = "It is most fortunate that you took the time to search for this.\n\nNo one would have expected the Burning Blade to be in possession of something so powerful!", objectives = "Sorrem at Furien's Post wants you to find the Ancient Summoning Ritual in Thunder Axe Fortress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14226] = { id = 14226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble Under Foot", description = "Look at you. Doing errands. Quite responsible of you. You're moving up up up, you are... up up!\n\nThere be demons ahead! Demons of many unpleasant kinds. Demons that would quite like your innards! Legash demons of a southeasternly heading! But do not worry. No no, no reason to worry, for I shall provide you with a companion!\n\nPoint, bugify, squash. Point, bugify, squash! Quite efficient. Quite messy too... but again, worry not. No no, worry not, for afterwards, we don't have to clean up!", completion = "<Archmage Xylem appears to be doing some kind of dance as he turns to you.>\n\nDo not fret, and better yet, do not forget, to do not let the bug juice set or you will regret... well, you'll regret the smell of your boots really! It won't smell good today and it won't smell good even more tomorrow!", objectives = "Use your Personal Arcane Assistant to turn 12 Legash demons into insects and then squash them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14227] = { id = 14227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putting Their Heads Together", description = "So it's true....\n\nThe parchment you discovered in Thunder Axe Fortress details a powerful summoning ritual. One stronger than the Burning Blade have ever been known to possess.\n\nClearly, this rite must be stopped at all costs!\n\nPerhaps if this demon were summoned forth prematurely the crisis could be averted.", completion = "You diverted what would have been a serious crisis, {class}.\n\nIf that summoning was delayed just a bit longer, the demon would have become far too powerful for our small forces here to contend with.\n\nPlease accept this gift as our thanks for your service.", objectives = "Collect 100 Bleached Skulls from Thunder Axe Fortress, place them at the Burning Blade Summoning Circle, then kill Nazargen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14230] = { id = 14230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manual Labor", description = "The local demons seem to get quite a kick out of stealing all of our arcane manuals. I highly doubt most of them can even read, so they're probably doing it just to spite us.\n\nI could care less about most of the books they've taken, but they took an Abjurer's Manual that I'm going to need if there's any hope of keeping apprentices like you alive amidst Xylem's \"trials.\" Find the demons at the Lagash Encampment to the southeast and retrieve the Abjurer's Manual.\n\nThat's all. Scoot.", progress = "And here you are... back... talking to me again. I assume this means that you have my book?", completion = "Peachy. Back to work then.\n\nThanks, snookums.", objectives = "Retrieve the Abjurer's Manual from the Lagash Encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14231] = { id = 14231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Useless quest record" }
quests[14232] = { id = 14232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ears Are Burning", description = "Sorrem has made no secret of his disdain for the Burning Blade at Thunder Axe Fortress.\n\nSurely, proof of their demise would be of value to him.", progress = "What have you there, {class}?", completion = "Ears of the Burning Blade?\n\n<Sorrem smiles.>\n\nWell done, {class}. This is just a shadow of what will soon become of that vile cult!", objectives = "You are to bring 25 Burning Blade Ears to Sorrem at Furien's Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14233] = { id = 14233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orcs Can Write?", description = "Looking through the dead orc's belongings, you find a field journal. Though it is heavily water damaged, the writing is still legible, if barely.\n\nFlipping through the pages, an interesting story unfolds. Good thing you decided to study Orcish.\n\nLike the Trade Prince's yacht, the orcs were fired upon by Alliance warships. You do remember an orc warship that you passed right before the Alliance opened fire. Maybe they were firing on the orcs instead of your ship?\n\nStupid orcs! They got you sunk!", progress = "{name}, find anything interesting in the cavern?", completion = "Orcs?! They were sunk and stranded too?  And now the Alliance are on the island? Do you think they're going to kill us?\n\n<Sassy looks thoughtful.>\n\nI think it's time for a little sitdown with these orcs.", objectives = "Take the Field Journal to Sassy Hardwrench at Shipwreck Shore on the Lost Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14234] = { id = 14234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Enemy of My Enemy", description = "I hate to ask you to do this, but I guess it's why they pay you the big bucks. Can you deliver that dead orc's field journal to whoever is in charge up at their camp?\n\nBased on the writing in the book, they should be located at the top of the island, up the incline past the Kaja'mite cavern to the southeast.\n\nGood luck, {name}. I always liked you.", progress = "<The orc narrows her eyes at you.>\n\nYou must have been on the {race} slave ship that was sunk. What's that you have in your hand?", completion = "<The orc makes a move to grab the field journal from you, but then stops herself, exhaling deeply.>\n\nI apologize. It has been a very rough couple of days for all of us.\n\nI am Aggra. All of us here are what remains of the crew of the Draka's Fury.\n\nPerhaps we can work together. We have a common enemy in the Alliance. Their SI:7 assassins are all over this island and they're not going to stop until we're all dead.", objectives = "Deliver the Field Journal to Aggra at the Horde Base Camp on the Lost Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14235] = { id = 14235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vicious Vale", description = "Our hunter, Kilag Gorefang, and a few scouts, traveled into the vale down the path to the west. They're ...searching for... 'precious cargo'... that we were guarding when the filthy Alliance sunk our ship.\n\nThe way is blocked by deadly plants and they have not been able to break through.\n\n{name}, prove your worth as a goblin and a {class}. Journey into the Vicious Vale to find Kilag.", completion = "{race}, can you fight?\n\nFor your sake, I hope so. Otherwise, there may be no breaking through this hell of killer plants.", objectives = "Find Kilag Gorefang in the Vicious Vale on the Lost Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14236] = { id = 14236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weed Whacker", description = "<Kilag barely has time to acknowledge you between rifle shots, but his eye does linger a moment on your Goblin All-In-1-der Belt appreciatively.>\n\nNow is the time for creative solutions. Pull something out of that belt and get to work!\n\n<Thinking about the situation for a moment, an idea comes to your mind and it's just crazy enough to work!>", progress = "There are still too many for us to get through.\n\nHave faith in yourself, {name}. Let your true warrior heart shine through.", completion = "I saw it with my own eyes, and still I do not believe it!\n\nYou have our thanks and the debt of our lives, little {race}. I hope that soon we can repay you the honor.\n\nMay I ask a small favor of you while my scouts and I move on?", objectives = "Use the Weed Whacker within your Goblin All-In-1der Belt to mow down 100 of the plants within the Vicious Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14237] = { id = 14237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forward Movement", description = "Kilag should be in position by now. It is time for you to move forward to the Wild Overlook. The rest of us will pack up here and move out soon.\n\nJust follow the path northwest through the Vicious Vale. Not so vicious any longer thanks to you, eh?\n\nKilag and his scouts will be keeping themselves hidden just off the path, but the SI:7 assassins are sure to spot them soon, so hurry!", completion = "Throm-Ka, {name}. We have a problem.", objectives = "Find Kilag Gorefang and his scouts at the Wild Overlook on the Lost Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14238] = { id = 14238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infrared = Infradead", description = "Keep your voice down. The glen north and west of here is crawling with Alliance assassins.\n\nUnfortunately, we haven't been able to spot them. The cowards! They hide and won't fight face-to-face.\n\nYou goblins are known for your wondrous goggles. Surely you have a pair that will allow you to see them?\n\nI need you to team up with one of my scouts and kill any of the SI:7 assassins that you spot.", progress = "You got them all?", completion = "Well done, {name}, well done. We'll make an orc of you yet!\n\nTime to move on. We'd better hurry.", objectives = "Kill 10 SI:7 Assassins.\n\nIf something happens to your Orc Scout, return to Kilag to see if he has another for you to team up with.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14239] = { id = 14239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Go Into the Light!", sourceObjective = "It's up to you now. Are you going to come back to life and be the hero that your fellow survivors need you to be, or are you going to rest for eternity here?\n\nOnly you can decide.\n\nDon't go into the Light, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[14240] = { id = 14240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Cliffs", description = "I sent Scout Brax forward along the road to the cliffs overlooking the beach to the west.\n\nI am going to put you onto Bastia. Travel down the path and let Brax know that we are going to take a different route.\n\nWe'll see you at the attack on the Alliance beachhead!", completion = "Hello, little {race}. Bastia is fast, no?\n\nWe have something very important that needs doing. Can you help us?", objectives = "Speak with Scout Brax on the path down the cliffs north of the Savage Glen on the Lost Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14241] = { id = 14241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get to the Gyrochoppa!", description = "The Alliance have stolen something of vital importance to the Horde. It is being held out on their ships.\n\nAt the other end of the beach is a gyrochoppa. Our battlesworn will cover your approach.\n\nGo retrieve the keys to the flying machine from one of their operatives.\n\nFly out to their flagship, the Vengeance Wake, and retrieve our precious cargo!", progress = "Hmm, looks like overly-complicated gnomish engineering with lots of unnecessary instrumentation and safety precautions.", completion = "Hmm, where the heck is the ignition?\n\nIt'll be a wonder if it flies without doing something weird, like turning into a chicken or shrinking down to the size of an ant.\n\nHey look, someone left their loose change in the ashtray! What else is in there?", objectives = "Retrieve the Gyrochoppa Keys.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14242] = { id = 14242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precious Cargo", description = "They said that their \"precious cargo\", whatever that is, is being held out on the Alliance ship, the Vengeance Wake.\n\nThere's only one thing to do... fly this thing out there and retrieve it!", progress = "Perhaps you can help me to get out of this arcane cage?", completion = "If not for you, I would surely be on my way back to Stormwind to be paraded as a trophy and a slave.\n\nThe Alliance dogs found me unconscious on the shore and put me in this magical cage. It was keeping me from connecting with the elements.\n\nNo longer!", objectives = "Locate the precious cargo below deck on the Alliance ship, Vengeance Wake, off the shore of the Lost Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14243] = { id = 14243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Revenge", description = "Brothers of Earth and Fire, hear me! Sisters of the Water and Air, heed my call!\n\nAzeroth stands on the brink, its existence near an end! Lend me your power as in times past with my ancient ancestors. Allow me to channel your will through this child of Kezan.\n\nLet us put an end to those who would keep us from healing the world!", completion = "You have done what few others could have, {name}. Our world owes you a debt larger than you can possibly understand.", objectives = "Use the powers of the Cyclone of the Elements to slay 50 Alliance Sailors.\n\nOnce this is done, you will be flown to the Wild Overlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14244] = { id = 14244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up, Up & Away!", description = "While you were rescuing the Warchief and saving us all from the Alliance, Foreman Dampwick built this rocket sling to shoot us over the shark-infested strait to the bigger island.\n\nLuckily for us, the foreman managed to salvage a Town-In-A-Box from the shipwreck. Once you get it set up, we'll have a town of our own. I can't wait to sleep in a bed again!\n\nDampwick's down there at the Landing Site, waiting for you. Why don't you take the next rocket over?", completion = "{name}, I sure am glad you survived the trip... not everyone did!", objectives = "Survive the Rocket Sling shot across the Dire Strait.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14245] = { id = 14245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's a Town-In-A-Box", description = "The trade prince had an entire town-in-a-box in the ship's hold! I managed to recover it while you were out saving all of our skins.\n\nDo you want to do the honors? All you have to do is climb to the top of that huge pile of explosives and push the plunger, and whamo kablamo, instant town!", completion = "<cough, cough!>\n\nHey! Where's the dock?! Someone stole the dock and the oil refinery from our town-in-a-box!\n\nWho would do such a thing?\n\nWhere's the Trade Prince?", objectives = "Climb to the top of the mountain of explosives and use the Town-In-A-Box Plunger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14246] = { id = 14246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Early Adoption", description = "As the region becomes more lush, the creatures of the desert are being forced into increasingly confined spaces.\n\nA particularly distressing result is the impending extinction of the local swoops. Predators feast on the birds and their eggs when they take nest.\n\nI have acquired some swoop eggs from Tanaris and coated them with an irresistible pheromone. Place one in each nest you find, then protect it until a swoop comes to carry it off.\n\nYou will be doing a service to the balance of this land.", completion = "You have done well, {class}.\n\nThis land is in your debt.", objectives = "Place 3 Swoop Eggs in Swoop Nests and protect them until they are collected.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14247] = { id = 14247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stubborn Lands", description = "By authority of the Cenarion Circle, I am charged with turning these harsh lands into lush prairie.\n\nThe lands south of here welcomed the growth, but something here is fighting back - resisting the replenishment.\n\nPerhaps your eyes can succeed where mine have failed.\n\nPlease, {race}. Scour these lands and discover the source of the desert's stubbornness.", completion = "You look around, scanning the horizon for what might be responsible for placing this stone here....", objectives = "Thunk at Thunk's Abode wants you to find the Unnatural Outcropping.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14248] = { id = 14248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help Wanted", description = "Great news! Foreman Dampwick has uncovered a cave full of kaja'mite on the island! What are the odds?\n\nOf course, there's a downside. He took some of the survivors with him to help mine the ore, but none of them have made it out.\n\nCrazy as it sounds, the foreman said that there are monkeys in the cave... with mining picks! They're mining the kaja'mite! How is that even possible?\n\nCan you head southeast to the cavern? The foreman is standing just outside the entrance.", completion = "Boss! Er, well, I guess you're not the boss anymore, but still, good to see you!\n\nCan you believe it? We've got a cave full of intelligent killer monkeys mining Kaja'mite!", objectives = "Speak with Foreman Dampwick outside of the Kaja'mite Cavern on the Lost Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14249] = { id = 14249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shear Will", description = "I'd be amazing! At archmagery. Amazing! He won't even talk to me because I don't have a stupid robe and hat. Pffft.\n\nThe most amazing archmage this land has ever seen can't just have any robe and hat. I need to show him that I'm something special, and I know just how to do it.\n\nGo out there and kill some of those hippogryph things. Bring me back a TON of feathers.\n\nYou heard me! A whole bunch of feathers! Go go, I'll have the robe ready for them by the time you get back.", progress = "My robes looking pretty good. Did you bring those feathers?", completion = "Ha ha! Perfect! Let me toss this together really fast. The Archmage is sure to be taken in by my style!", objectives = "Obtain 80 Pristine Thunderhead Feathers from the Hippogryphs near the Ruins of Nordressa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14250] = { id = 14250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renewable Resource", description = "We're going to need some more animate basalt. There's only one reliable source for that in the area, a mountain giant named Balboa. We can't be killing the mountain giant if we want to keep stocked in the stuff long term, so we've just been chipping off pieces at a time.\n\nYou'll be able to see his path northeast and east of here. Find him, place the charge ahead on the path, and then hide until it goes off. Once he's cleared the area, you should be able to retrieve the basalt and bring it back to me.", progress = "I heard a few explosions. I can hardly tell if one of them was yours or not... these goblins can be quite a nuisance.", completion = "Good work. This should keep us for another few hours before we have to go back for more.\n\nHe doesn't seem to be the brightest of giants. I expect we'll be able to keep doing this for a while before he catches on.", objectives = "Use the Arcane Charge to retrieve 5 Animate Basalt from Balboa near the Ruins of Nordressa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14251] = { id = 14251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Beginnings", description = "There's never been danger of centaur attack this far north before. Someone put 'em up to it, I just know it!\n\nRegardless, I'm wiped out. I had everything invested in this haul.\n\nFortunately, there's one thing no centaur can take from me and that's goblin ingenuity! I'll start from scratch and build an empire!\n\n<Bizby spots a scorpion in the distance.>\n\nThere's always a market for poison. Whatdya say, friend?", progress = "Let's have a look at those scorpion tails, friend.", completion = "This is how I got my start, you know.\n\nSlingin' poison to the rogues in Orgrimmar. Ahh, those were the days....", objectives = "Collect 15 Scorpion Stingers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14252] = { id = 14252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good Gold For Bad Tail", description = "I need a crateload of tail, {class}! And not just any kind of tail. The tail I'm after needs to be old - ancient even. The more decrepit the better.\n\nThe scales of a basilisk's tail are unique in that they harden with age without becoming brittle. The hardened scales are ideal for the production of certain armors.\n\nIt's been many years since I've been reduced to peddling lizard scales, but who knows, maybe it'll build even more character in me! If that's even possible....", progress = "How's the search for tail coming, {name}?", completion = "That'll do, {class}.\n\nA few more friends like you and I'll be back on my feet in no time!", objectives = "Find 15 Aged Basilisk Tails.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14253] = { id = 14253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fletch Me Some Plumage!", description = "Say, {class}, while you're out there exploring the desert wastes, do me a favor?\n\nKeep an eye out for Dread Swoops. Their oily feathers make for the best fletching, and to the right buyer they can fetch a handsome price.\n\nLucky for you, I know all of the right buyers!", progress = "How is the search for swoops coming?", completion = "Well now, that's quite a load of feathers, {class}.\n\nThey'll make for a good pillow 'til I get 'em to market!", objectives = "Collect 25 Dread Swoop Feathers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14254] = { id = 14254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heavy Metal", description = "You have a strong feeling that this stone is somehow responsible for the region's refusal to accept the encroaching regrowth.\n\nLooking off to the west, you notice a trail of smoldering debris that appears to be related to this mystery.\n\nYou surmise that clearing the debris might assist Thunk's efforts here.\n\nAnd who knows what this stuff might be good for?", progress = "Whatcha got there, {class}?", completion = "What's this?\n\n<Bizby examines the ore.>\n\nWahoo! I know someone who will be most interested in acquiring these samples.\n\nMost generous in payment for them as well, I'll wager.\n\nHere, {class}. Take this as your finder's fee.", objectives = "You are to collect 7 pieces of Element 116 and bring them to Bizby at Bizby's Caravan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14255] = { id = 14255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ethel Rethor", description = "We have plenty of enemies in this region without raising the ire of the Cenarion Circle.\n\nWhen we established our post here, we were asked to keep a watch over one of their researchers.\n\nKorrah was last seen at the tower to the west. Do be a dear and pay her a visit. It's been some time since we've bothered to check on her.", completion = "It is good that you have come.\n\nThere is grave danger looming here.", objectives = "Cerelia at Furien's Post wants you to speak to Korrah at Ethel Rethor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14256] = { id = 14256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emerging Threat", description = "I am all that remains of my company, sent to monitor the many changes on this coast of Desolace.\n\nI have reported of the dramatic increase of naga here, but to no effect.\n\nMy peers are focused on other crises, so I must ask you, a stranger, to assist me in my research.\n\nFirst, though, allow me to show you the threat we face.", completion = "So now you see. These are not a simple band of displaced naga, but a well organized army, capable of great devastation.\n\nDo you agree to assist me in my investigation?", objectives = "Korrah wants you to speak to her when you are ready to be shown the Naga threat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14257] = { id = 14257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slitherblade Slaughter", description = "Time and again, the naga have proven to be enemies to the balance of nature. I have no qualms with the spilling of their blood.\n\nYour best efforts though, would barely put a dent in their forces here. Where one falls, two seem to rise in their place.\n\nI have a plan, {class}. Your objective is not merely to take the lives of the enemy, but to gather components necessary for the next stage of our investigation....", progress = "Have you collected the components I require?", completion = "You have done well, {class}. But I'm afraid that your work here is just beginning.", objectives = "Collect 10 Slitherblade Bones from Slitherblade Naga, 30 Slitherblade Scales from Slitherblade Sorceresses, and 4 Slitherblade Fins from Slitherblade Warriors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14258] = { id = 14258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mortar the Point", description = "The Naga started making a move on the peninsula here after we finished building this rocketway terminal. But there's no problem in this world that can't be solved with gratuitous firepower! That's what my daddy used to say. Before the accident.\n\nI'm running short on supplies, though. Do me a favor and collect the mortar shells I left stockpiled in the Secret Lab just west of here. Keep me supplied and I'll let you call in the artillery strikes!", progress = "I hope you have more ammo for me. I've got nothing to shoot off over here but my mouth!", completion = "Sweet! Beautiful! Brilliant! Who loves you?\n\nWith my mortars re-supplied, I can help you as you assault the Naga east of here. Use these markers to call in an artillery strike anywhere on the cliffs, and I'll splatter the whole area with fiery hurt. Oh delicious, merciless, random destruction! I hope you're well-armored...", objectives = "Collect 5 Goblin Mortar Shells from the Secret Lab complex in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14259] = { id = 14259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Mortars, More!", description = "Thanks for helping me restock my supplies, {name}.\n\nI'll tell you what, bring me more mortars from the lab, and I'll keep supplying you with artillery signals. With me on the trigger and you in the field, we'll blast these cliffs until they go crashing into the sea!", objectives = "Collect 5 Goblin Mortar Shells from the Secret Lab complex in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14260] = { id = 14260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going Deep", description = "I have fashioned a charm that will allow you to infiltrate the naga, giving you the appearance of one of their own.\n\nWith this disguise, you will be able to speak and understand their language. They will be unable to discern your true identity.\n\nBut beware! The sharks and other sea creatures here will expose you for all to see. Avoid them at all costs.\n\nNow go. Speak to the Priestess of Azshara and do what you must to learn of their purposes here.", completion = "Don't just stand around, when there is so much to be done!\n\nMust I instruct everyone on each detail?", objectives = "Use the Slitherblade Charm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14261] = { id = 14261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ice Cold", description = "I've got the perfect solution to our drake problem. My very own Cryomatic 16.\n\nI originally developed it to freeze my workers during transport and between shifts so that I wouldn't have to feed and entertain them, but there were... complications. It should be perfect for dropping these drakes out of the sky though!", completion = "What? So you didn't bring any of the drake pieces back? Disappointing.\n\nI knew I should have made you sign a contract before I sent you out...", objectives = "Use the Cryomatic 16 to freeze and kill 8 Sable Drakes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14262] = { id = 14262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Gut a Fish", description = "It tries my patience, defending against creatures who can disappear into the sea at will and emerge where they please. But I will not back down until their like has been wiped from Azshara.\n\nSpitelash Naga have slithered up the cliff walls and are besieging this post from the east. Destroy them, {name}. Gut them head to tail, so that they may know the full fury of my Horde.", completion = "<Torg scans the horizon.> And still they come! They are like a plague, {name}. But with strength like yours, we will crush them. Someday.", objectives = "Slay 6 Spitelash Stormfuries and 6 Spitelash Seacallers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14263] = { id = 14263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waste of Thyme", description = "Living Ire Thyme. I must have more! Be quick about it, will you?", progress = "Do you have that thyme for me?", completion = "Perfect. It's quite interesting how useful the most random things end up being to incantations of this sort.\n\nSo much more to learn!", objectives = "Collect 8 bundles of Living Ire Thyme near the Ruins of Nordressa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14264] = { id = 14264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wetter Than Wet", description = "Neptulon's minions have arrived here and are doing all they can to thwart us. Clearly, they've discovered our motives.\n\nThis only confirms my suspicion that what we seek is indeed somewhere in these ruins!\n\nThese water elementals are no match for our forces! Take this trident and use it to destroy the worthless servants of the Tidehunter.\n\nWhen we find what we seek here, Neptulon himself shall fear for his life!", progress = "Tell me, minnow. Have you done as I asked?", completion = "The enemy's ranks are thinning, little minnow.\n\nPerhaps you are worthy of assisting in our search....", objectives = "Defeat 5 Servants of Neptulon. (You must be in naga form when you defeat them.)\n\nIf you lose your Slitherblade Trident, speak to Valishj.\n\nIf you lose your Slitherblade Charm, speak with Korrah at Ethel Rethor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14265] = { id = 14265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Instructor", description = "Most of us made it here alive... but there are worgen on this side of the city as well.\n\nWe're going to continue heading south once everyone's accounted for.\n\nThat reminds me, someone was asking about you.  A fellow by the name of Cleese said you were one of his students and wanted to make sure you were all right.", completion = "{name}!  Where have you been?\n\nAnyway... it's great to see you in one piece.", objectives = "Speak to Sergeant Cleese in the Military District.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14266] = { id = 14266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charge", description = "You're alive, {name}!  That must mean I did something right.\n\nIt's a shame our lessons were cut off a little short.  But, as you go and learn on your own, you'll start to discover new techniques.\n\nGo get some more experience, learn something new, and then try it out against the bloodfang worgen to our west.", completion = "Excellent work!", objectives = "Reach level 3 to learn Charge. Practice using Charge against a Bloodfang Worgen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14267] = { id = 14267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigating the Sea Shrine", description = "The Naga invaders have set up a series of shrines along the cliffs. I don't know their purpose, {name}, but I believe they're strengthening our foes. I need someone to get in there and root out this threat.\n\nOne nearby shrine is lightly defended: Cross the first bridge east of here and then head north towards the bay. You'll find it on a small outcropping. Investigate that shrine and come back with some info I can use.", completion = "The stone in the center of this shrine emits a faint glow and roars with the power of the angry sea.", objectives = "Investigate the Naga shrine for Torg Twocrush.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14268] = { id = 14268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deep Impact", description = "Queen Azshara seeks entrance into the plane of water, for what I do not know.\n\nShe believes that the ancients held the keys to finding its location.\n\nI have personally been charged with scouring the ruins in this region, and none shall rest until we discover the secrets we seek!\n\nSubmerged just to the north are a concentration of ruins. Use this staff to search through the rubble.\n\nReturn to me only when you have located that which we seek!", progress = "Could it be....?", completion = "Yes! You've found it!\n\nNeptulon's engravings... there can be no mistake!", objectives = "Priestess Valishj wants you to find the Ancient Engravings of Neptulon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14269] = { id = 14269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Someone's Looking for You", description = "Most of us made it here alive... but there are worgen on this side of the city as well.\n\nWe're going to continue heading south once everyone's accounted for.\n\nThat reminds me, someone was asking about you.  A woman named Loren... she seemed a little disappointed when I told her you were all right.\n\nI think she mentioned she owes you money.", completion = "Oh, hey!  There you are!", objectives = "Speak to Loren the Fence in the Military District.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14270] = { id = 14270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Keystone Shard", description = "The air around this strange stone crackles with energy. The stone itself is smooth and icy cold. It pulses periodically as you run your hands over it, like the crashing of surf.\n\nA wedge-shaped piece appears to be missing from the top surface of the artifact. This 'keystone shard' is likely the key to unlocking the secrets of the stone. Search the grounds near the temple and locate the keystone shard.", progress = "The Naga power stone pulses with an expectant hum.", completion = "The keystone shard slides into place and previously invisible runes suddenly erupt onto the surface of the stone, shimmering in blue and violet hues. Your knees buckle as powerful arcane currents suddenly race into your body...", objectives = "Find the Keystone Shard nearby.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[14271] = { id = 14271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Twocrush", description = "A magical barrier pulses around you, chilling your bones. You feel secure behind this enchanted wall.\n\nTorg Twocrush will want to know what you've discovered here!", completion = "An energy barrier, you say? This explains a great deal! I've seen firsthand how Naga leaders have been able to turn aside the blades of some of my best warriors.\n\nNow we know the source of their power, {name}. Let's finish this!", objectives = "Return to Torg Twocrush at the Southern Rocketway Terminus in Azshara with news of your discovery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
